// ══════════════════════════════════════════════════════
// SOCKET LISTENER — registered once per session
// Lets the GM push any tool panel directly to a player's
// screen without the player needing to run the macro.
// Uses the dnd5e system socket channel which is always
// available in a dnd5e world, no module required.
// ══════════════════════════════════════════════════════


// ======================================================
// DRACOUROBOROS DOWNTIME PROJECT ENGINE v4.0 — UNIFIED
// Foundry VTT v14 / D&D5e
//
// SINGLE MACRO — contains the full hub, GM request dashboard,
// GM-to-project/training sync, and the standalone workbench,
// all sharing one data layer and one history log.
//
// Run this one macro. Everything is accessible from the hub.
// ======================================================

const MODULE_SCOPE = "dracouroboros-downtime";

const KEYS = {
  stars:     "dracouroborosDowntimeStars",
  history:   "dracouroborosDowntimeHistory",
  requests:  "dracouroborosDowntimeRequests",
  projects:  "dracouroborosCraftingProjects",
  training:  "dracouroborosTrainingTracks",
  resources: "dracouroborosResourceLedger",
  relations: "dracouroborosFactionNpcRelations",
  boons:     "dracouroborosDowntimeBoons"
};

// ── World-level shop persistence via game.settings ────
// Shops are world data, not actor data — they persist across
// sessions and are accessible to all GMs.

const SHOP_SETTING_KEY = "dracouroborosSavedShops";

function shopSettingsInit() {
  if (game.settings.settings.has(`${MODULE_SCOPE}.${SHOP_SETTING_KEY}`)) return;
  game.settings.register(MODULE_SCOPE, SHOP_SETTING_KEY, {
    name:    "Downtime Master Saved Shops",
    hint:    "Persisted shop data for the Downtime Engine shop generator.",
    scope:   "world",
    config:  false,
    type:    Array,
    default: []
  });
}

function getSavedShops() {
  try {
    shopSettingsInit();
    return foundry.utils.deepClone(
      game.settings.get(MODULE_SCOPE, SHOP_SETTING_KEY) ?? []
    );
  } catch { return []; }
}

async function setSavedShops(shops) {
  shopSettingsInit();
  await game.settings.set(MODULE_SCOPE, SHOP_SETTING_KEY, shops);
}

async function saveShop(shopConfig, pricedStock) {
  const shops = getSavedShops();
  // If this shop already has an id (re-save), update in place
  const existing = shopConfig.shopId
    ? shops.findIndex(s => s.shopId === shopConfig.shopId)
    : -1;

  const record = {
    shopId:      shopConfig.shopId || uid("shop"),
    shopName:    shopConfig.shopName,
    shopKeeper:  shopConfig.shopKeeper  || "",
    shopNotes:   shopConfig.shopNotes   || "",
    locationKey: shopConfig.locationKey,
    sizeKey:     shopConfig.sizeKey,
    categoryKey: shopConfig.categoryKey,
    fluctPct:    shopConfig.fluctPct,
    savedAt:     nowIso(),
    pricedStock  // full stock snapshot — reopens without re-querying compendiums
  };

  if (existing >= 0) {
    shops[existing] = record;
  } else {
    shops.push(record);
  }

  await setSavedShops(shops);
  return record;
}

async function deleteShop(shopId) {
  const shops = getSavedShops().filter(s => s.shopId !== shopId);
  await setSavedShops(shops);
}

// Initialise on macro load (registers the setting if not already registered)
shopSettingsInit();

