const ACTIVITY_DATA = {
  "Buying a Magic Item": {
    cost: 1, dc: 10, category: "Market",
    checks: "Usually 1 check: Charisma (Persuasion).",
    description: "Search for a magic item to purchase. The item found is drawn from your tier's weighted magic item tables — the same tables used by the treasure generator — so rewards are level-appropriate. Higher Persuasion rolls grant a reroll if the first result is unsatisfying.",
    defaults: [["per","cha"],["na","cha"],["na","cha"]],
    outcome: (avg, successes) => {
      if (successes === 0) return "No market found. No item available this downtime period.";
      if (avg <= 10) return "Market found — one item available (tier-appropriate table, 1 roll).";
      if (avg <= 20) return "Good contacts — one item available, with a reroll option if unsatisfying.";
      if (avg <= 30) return "Excellent contacts — two items to choose from.";
      return "Master network — three items to choose from.";
    },
    reward: async (successes, avg, _ctx, actor) => {
      if (successes === 0) return null;

      // Determine character tier from level
      // dnd5e stores total level on actor.system.details.level (PC) or .cr (NPC)
      const charLevel = Number(
        actor?.system?.details?.level ??
        actor?.system?.details?.cr    ??
        actor?.system?.level          ?? 1
      ) || 1;

      const tier = charLevel <= 4 ? 1 : charLevel <= 10 ? 2 : charLevel <= 16 ? 3 : 4;
      const cfg  = TREASURE_TIER_CONFIG[tier];

      // Number of rolls: 1 below avg 10, reroll chance at 11–20, 2 at 21–30, 3 at 31+
      const numRolls = avg > 30 ? 3 : avg > 20 ? 2 : 1;

      // Roll each item from the tier-weighted table
      const results = [];
      for (let i = 0; i < numRolls; i++) {
        const tableKey = treasureChooseWeighted(cfg.weights);
        let   item     = treasureRollOnTable(tableKey);
        if (item.category === "scroll") item = treasureResolveScroll(item);
        results.push(item);
      }

      // Grant each to the actor's sheet
      const granted = [];
      for (const item of results) {
        try {
          const data = await treasureMakeActorItem(item, tier);
          if (data) {
            await actor.createEmbeddedDocuments("Item", [data]);
            granted.push(item.name);
          }
        } catch (err) { console.error("[Buy Magic Item] Grant failed:", err); }
      }

      return granted.length > 0
        ? { type:"items", names: granted,
            note: `Tier ${tier} (level ${charLevel}) — ${cfg.weightLabel}: ${granted.join(", ")}` }
        : null;
    }
  },
  "Crafting": {
    cost: 1, dc: 10, category: "Project",
    checks: "Usually 1 relevant tool check. Complex projects may use up to 3 checks.",
    description: "Craft items, consumables, or progress a blueprint.",
    defaults: [["smith","str"],["na","str"],["na","str"]],
    outcome: (avg) => {
      if (avg < 10)  return "Failed progress.";
      if (avg <= 14) return "Poor progress.";
      if (avg <= 19) return "Average progress.";
      if (avg <= 24) return "Good progress.";
      if (avg <= 29) return "Superior progress.";
      return "Masterwork progress.";
    },
    reward: () => null
  },
  "Crime": {
    cost: 2, dc: 15, category: "Risk",
    checks: "Normally 3 checks: Stealth, Thieves' Tools, then Investigation/Perception/Deception.",
    description: "Attempt criminal work for profit.",
    defaults: [["ste","dex"],["thief","dex"],["inv","int"]],
    hasStake: true,
    outcome: (_avg, successes) => {
      if (successes === 0) return "Caught and punished.";
      if (successes === 1) return "Crime fails, but you escape.";
      if (successes === 2) return "Partial success. Gain half payout.";
      return "Full success. Gain full payout.";
    },
    reward: (successes, _avg, ctx) => {
      const stake = ctx.stake || 0;
      if (successes === 0) return { type:"gold", gold: -stake, note:"Caught — stake lost as fine/cost." };
      if (successes === 1) return null;
      if (successes === 2) return { type:"gold", gold: Math.floor(stake * 0.5), note:`Crime: half payout (+${Math.floor(stake*0.5)} gp)` };
      return { type:"gold", gold: stake, note:`Crime: full payout (+${stake} gp)` };
    }
  },
  "Gambling": {
    cost: 2, dc: 12, category: "Risk",
    checks: "Normally 3 checks: Insight, Deception, Intimidation. Gaming Set may replace a relevant check.",
    description: "Risk gold in games of chance.",
    defaults: [["ins","wis"],["dec","cha"],["itm","cha"]],
    hasStake: true,
    outcome: (_avg, successes) => {
      if (successes === 0) return "Lose stake and accrue debt equal to it.";
      if (successes === 1) return "Lose half your stake.";
      if (successes === 2) return "Gain your stake plus half again.";
      return "Gain double your stake.";
    },
    reward: (successes, _avg, ctx) => {
      const stake = ctx.stake || 0;
      if (successes === 0) return { type:"gold", gold: -stake, note:`Gambling loss: −${stake} gp` };
      if (successes === 1) return { type:"gold", gold: -Math.floor(stake * 0.5), note:`Gambling: lost half stake (−${Math.floor(stake*0.5)} gp)` };
      if (successes === 2) return { type:"gold", gold: Math.floor(stake * 0.5), note:`Gambling win: stake + half (gain +${Math.floor(stake*0.5)} gp net)` };
      return { type:"gold", gold: stake, note:`Gambling win: doubled stake (+${stake} gp net)` };
    }
  },
  "Pit Fighting": {
    cost: 1, dc: 12, category: "Risk",
    checks: "Normally 3 checks: Athletics, Acrobatics, Constitution/raw check or attack roll substitute.",
    description: "Fight in organized bouts.",
    defaults: [["ath","str"],["acr","dex"],["none","con"]],
    outcome: (_avg, successes) => {
      if (successes === 0) return "Lose your bouts and earn nothing.";
      if (successes === 1) return "Win 50 gp.";
      if (successes === 2) return "Win 100 gp.";
      return "Win 200 gp.";
    },
    reward: (successes) => {
      const gold = [0, 50, 100, 200][Math.min(successes, 3)];
      return gold > 0 ? { type:"gold", gold, note:`Pit Fighting prize: +${gold} gp` } : null;
    }
  },
  "Religious Service": {
    cost: 1, dc: 10, category: "Social",
    checks: "Usually 1 check: Religion or Persuasion.",
    description: "Serve a temple to earn divine favor.",
    defaults: [["rel","int"],["na","int"],["na","int"]],
    outcome: (avg) => avg <= 10 ? "No effect." : avg <= 20 ? "Earn one divine favor." : "Earn two divine favors.",
    reward: async (successes, avg, _ctx, actor) => {
      if (avg <= 10) return null;
      const numBoons = avg <= 20 ? 1 : 2;
      const presets  = BOON_PRESETS["Religious Service"] || [];
      const boonData = presets[0]; // Divine Favour is always the first
      if (!boonData) return null;

      const list    = getBoons(actor);
      const granted = [];
      for (let i = 0; i < numBoons; i++) {
        const boon = {
          id:          uid("boon"),
          name:        boonData.name,
          category:    "Religious Service",
          description: boonData.description,
          source:      boonData.source,
          created:     nowIso(),
          used:        false
        };
        list.push(boon);
        await grantBoonToSheet(actor, boon);
        granted.push(boon.name);
      }
      await setBoons(actor, list);

      return { type:"boons", names: granted,
               note: `${numBoons} divine favour${numBoons > 1 ? "s" : ""} granted` };
    }
  },
  "Research": {
    cost: 2, dc: 10, category: "Lore",
    checks: "Usually 1 Intelligence check: Investigation, Arcana, History, Nature, or Religion.",
    description: "Research lore about a person, place, monster, item, or mystery.",
    defaults: [["inv","int"],["na","int"],["na","int"]],
    outcome: (avg) => avg <= 5 ? "No useful lore." : avg <= 10 ? "Learn one piece of lore." : avg <= 20 ? "Learn two pieces of lore." : "Learn three pieces of lore.",
    reward: () => null
  },
  "Scribing": {
    cost: 1, dc: 10, category: "Project",
    checks: "Usually 1 check: Arcana.",
    description: "Scribe a spell scroll. Specify the spell in the Goal/Details field — on success the scroll is added to your sheet via the Spell Scroll Scribe.",
    defaults: [["arc","int"],["na","int"],["na","int"]],
    outcome: (avg) => avg < 10 ? "Scroll flawed or materials wasted." : avg < 15 ? "Scroll completed with a minor quirk." : avg < 20 ? "Scroll completed normally." : "Scroll completed exceptionally.",
    reward: (successes, _avg, ctx) => successes >= 1 && ctx.itemName
      ? { type:"scroll", itemName: ctx.itemName, note:`Scroll scribed: ${ctx.itemName}` }
      : null
  },
  "Selling Magic Items": {
    cost: 1, dc: 10, category: "Market",
    checks: "Usually 1 check: Charisma (Persuasion).",
    description: "Find a buyer for a magic item.",
    defaults: [["per","cha"],["na","cha"],["na","cha"]],
    hasStake: true,
    outcome: (avg) => avg <= 10 ? "Offer is 50% of base price." : avg <= 20 ? "Offer is 100% of base price." : "Offer is 150% of base price.",
    reward: (successes, avg, ctx) => {
      const base = ctx.stake || 0;
      const pct  = avg <= 10 ? 0.50 : avg <= 20 ? 1.00 : 1.50;
      const gold = Math.floor(base * pct);
      return gold > 0 ? { type:"gold", gold, note:`Magic item sold for ${gold} gp (${Math.round(pct*100)}% of ${base} gp base)` } : null;
    }
  },
  "Training": {
    cost: 4, dc: 10, category: "Training",
    checks: "Usually 1 weekly training check. Track total toward 135 for first training.",
    description: "Train a language, tool, stat, or special discipline.",
    defaults: [["none","int"],["na","int"],["na","int"]],
    outcome: (avg) => `Training progress added: ${avg}. Track toward 135.`,
    reward: () => null
  },
  "Work": {
    cost: 1, dc: 10, category: "Lifestyle",
    checks: "Usually 1 check: Athletics, Acrobatics, Intelligence with tools, Performance, or Charisma with instrument.",
    description: "Work a temporary job.",
    defaults: [["prf","cha"],["na","cha"],["na","cha"]],
    outcome: (avg) => avg <= 9 ? "Poor lifestyle." : avg <= 14 ? "Modest lifestyle." : avg <= 20 ? "Comfortable lifestyle." : "Comfortable lifestyle + 25 gp.",
    reward: (_s, avg) => avg > 20 ? { type:"gold", gold: 25, note:"Work: comfortable lifestyle bonus +25 gp" } : null
  },
  "Carousing": {
    cost: 1, dc: 10, category: "Social",
    checks: "Usually 1 Charisma check.",
    description: "Spend coin socialising, gambling lightly, and networking.",
    defaults: [["per","cha"],["ins","wis"],["na","cha"]],
    hasStake: true,
    outcome: (_avg, successes) => {
      if (successes === 0) return "Cause offense. Lose stake and may accrue a complication.";
      if (successes === 1) return "Make a useful contact. Lose stake.";
      if (successes === 2) return "Make a useful contact. Recoup half stake from a fortuitous opportunity.";
      return "Make a valuable contact. Recoup full stake.";
    },
    reward: (successes, _avg, ctx) => {
      const stake = ctx.stake || 0;
      if (successes === 0) return { type:"gold", gold: -stake, note:`Carousing: stake spent (−${stake} gp)` };
      if (successes === 1) return { type:"gold", gold: -stake, note:`Carousing: stake spent (−${stake} gp)` };
      if (successes === 2) return { type:"gold", gold: -Math.floor(stake*0.5), note:`Carousing: half stake recouped (−${Math.floor(stake*0.5)} gp net)` };
      return null; // full recoup — no net change
    }
  },
  "Relaxation": {
    cost: 1, dc: 0, category: "Recovery",
    checks: "No check required.",
    description: "Rest and recover. Gain inspiration for next session.",
    defaults: [["na","con"],["na","con"],["na","con"]],
    outcome: () => "Gain one inspiration for the next session.",
    reward: () => null
  },
  "Custom Activity": {
    cost: 1, dc: 10, category: "Custom",
    checks: "GM determines required checks.",
    description: "A custom downtime activity.",
    defaults: [["none","int"],["na","int"],["na","int"]],
    outcome: (_avg, successes) => `${successes} successful check(s). GM determines final result.`,
    reward: () => null
  }
};

