// ══════════════════════════════════════════════════════
// ACTOR ITEM HELPERS — create / consume 5e loot items
// ══════════════════════════════════════════════════════

/**
 * Create or increment a loot-type item on the actor sheet representing
 * one of our tracked resources. The item is tagged with a flag so we
 * can find it again reliably.
 */
async function grantResourceItem(actor, matEntry, quantity = 1) {
  const flagKey = `dtMaterial_${matEntry.name.replace(/\s+/g, "_")}`;

  // Look for an existing item with our flag
  let existing = actor.items.find(i => i.getFlag(MODULE_SCOPE, "dtMaterialKey") === flagKey);

  if (existing) {
    const newQty = (existing.system.quantity ?? 1) + quantity;
    await existing.update({ "system.quantity": newQty });
    return existing;
  }

  const rarityTag = matEntry.rarity || "Common";
  const edibleTag = matEntry.edible ? " [Edible]" : " [Non-edible]";

  const itemData = {
    name: matEntry.name,
    type: "loot",
    img: "https://assets.forge-vtt.com/65e70ddcf8447871c18a2b4d/macros/ChatGPT%20Image%20May%206%2C%202026%2C%2001_30_05%20PM.png",
    system: {
      description: {
        value: `<p><strong>Category:</strong> ${matEntry.category}</p>
                <p><strong>Source:</strong> ${matEntry.source}</p>
                <p><strong>Potential Use:</strong> ${matEntry.use}</p>
                <p><strong>Value:</strong> ${matEntry.value}</p>
                <p><strong>Rarity:</strong> ${rarityTag}${edibleTag}</p>
                <p><em>Tracked by the Downtime Master.</em></p>`
      },
      quantity: quantity,
      weight: 0,
      price: { value: 0, denomination: "gp" },
      rarity: rarityTag.toLowerCase().replace(/\s+/g, ""),
      identified: true
    },
    flags: {
      [MODULE_SCOPE]: {
        dtMaterialKey: flagKey,
        dtCategory: matEntry.category,
        dtSource: matEntry.source,
        dtEdible: matEntry.edible,
        dtValue: matEntry.value,
        dtRarity: matEntry.rarity
      }
    }
  };

  const [created] = await actor.createEmbeddedDocuments("Item", [itemData]);
  return created;
}

/**
 * Consume (decrement) the quantity of a tracked material item on the sheet.
 * Removes the item entirely if quantity reaches 0.
 * Returns { success, newQty, removed }.
 */
async function consumeResourceItem(actor, matName, quantity = 1) {
  const flagKey = `dtMaterial_${matName.replace(/\s+/g, "_")}`;
  const item    = actor.items.find(i => i.getFlag(MODULE_SCOPE, "dtMaterialKey") === flagKey);

  if (!item) return { success: false, newQty: 0, removed: false };

  const current = item.system.quantity ?? 1;
  const newQty  = current - quantity;

  if (newQty <= 0) {
    await item.delete();
    return { success: true, newQty: 0, removed: true };
  }

  await item.update({ "system.quantity": newQty });
  return { success: true, newQty, removed: false };
}

/**
 * Return all material items currently on the actor that were created
 * by the downtime engine (carry the dtMaterialKey flag).
 */
function getActorMaterialItems(actor) {
  return actor.items
    .filter(i => i.getFlag(MODULE_SCOPE, "dtMaterialKey"))
    .map(i => ({
      item:     i,
      name:     i.name,
      flagKey:  i.getFlag(MODULE_SCOPE, "dtMaterialKey"),
      category: i.getFlag(MODULE_SCOPE, "dtCategory") || "Material",
      qty:      i.system.quantity ?? 1
    }))
    .sort((a, b) => a.name.localeCompare(b.name));
}

// ══════════════════════════════════════════════════════
// UTILITY HELPERS
// ══════════════════════════════════════════════════════

function uid(prefix = "id") {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function safeText(value) {
  return Handlebars.escapeExpression(String(value ?? ""));
}

function nowIso() {
  return new Date().toISOString();
}

// ══════════════════════════════════════════════════════
// ACTOR HELPERS
// ══════════════════════════════════════════════════════

function characterActors() {
  return game.actors
    .filter(a => a.type === "character")
    .sort((a, b) => a.name.localeCompare(b.name));
}

function visibleActorsForUser() {
  return characterActors().filter(a => game.user.isGM || a.isOwner);
}

function controlledActor() {
  return canvas.tokens.controlled[0]?.actor ?? null;
}

function selectedOrFirstOwnedActor() {
  const sel = controlledActor();
  if (sel && (game.user.isGM || sel.isOwner)) return sel;
  return visibleActorsForUser()[0] ?? null;
}

// ══════════════════════════════════════════════════════
// FLAG HELPERS — single source of truth for all data I/O
// ══════════════════════════════════════════════════════

function getFlag(actor, key, fallback) {
  return foundry.utils.deepClone(actor.getFlag(MODULE_SCOPE, key) ?? fallback);
}

async function setFlag(actor, key, value) {
  await actor.setFlag(MODULE_SCOPE, key, value);
}

// Stars
function getStars(actor)         { return Number(actor.getFlag(MODULE_SCOPE, KEYS.stars) ?? 0); }
async function setStars(actor, v){ await setFlag(actor, KEYS.stars, Math.max(0, Number(v) || 0)); }

// History — every meaningful action writes here
function getHistory(actor)       { return getFlag(actor, KEYS.history, []); }
async function addHistory(actor, entry) {
  const history = getHistory(actor);
  history.push({ id: uid("hist"), date: nowIso(), ...entry });
  await setFlag(actor, KEYS.history, history);
}

// Requests
function getRequests(actor)           { return getFlag(actor, KEYS.requests, []); }
async function setRequests(actor, v)  { await setFlag(actor, KEYS.requests, v); }
async function addRequest(actor, req) {
  const list = getRequests(actor);
  list.push({ id: uid("req"), date: nowIso(), status: "Pending", player: game.user.name, ...req });
  await setRequests(actor, list);
}

// Projects
function getProjects(actor)           { return getFlag(actor, KEYS.projects, []); }
async function setProjects(actor, v)  { await setFlag(actor, KEYS.projects, v); }

// Training
function getTraining(actor)           { return getFlag(actor, KEYS.training, []); }
async function setTraining(actor, v)  { await setFlag(actor, KEYS.training, v); }

// Resources, Relations, Boons
function getResources(actor)          { return getFlag(actor, KEYS.resources, []); }
async function setResources(actor, v) { await setFlag(actor, KEYS.resources, v); }
function getRelations(actor)          { return getFlag(actor, KEYS.relations, []); }
async function setRelations(actor, v) { await setFlag(actor, KEYS.relations, v); }
function getBoons(actor)              { return getFlag(actor, KEYS.boons, []); }
async function setBoons(actor, v)     { await setFlag(actor, KEYS.boons, v); }

// ══════════════════════════════════════════════════════
// STAT HELPERS
// ══════════════════════════════════════════════════════

function getAbilityMod(actor, ability) {
  return Number(actor.system.abilities?.[ability]?.mod ?? 0);
}

function getProfBonus(actor) {
  return Number(actor.system.attributes?.prof ?? 0);
}

function getProfMultiplier(actor, checkKey) {
  const check = CHECK_DATA[checkKey];
  if (!check || check.type === "none" || checkKey === "na") return 0;
  const source = check.type === "skill"
    ? actor.system.skills?.[checkKey]
    : actor.system.tools?.[checkKey];
  if (!source) return 0;
  const raw = source.value ?? source.prof ?? source.proficient ?? 0;
  if (typeof raw === "number") return raw;
  if (raw === true) return 1;
  return Number(raw) || 0;
}

function profText(mult) {
  if (mult === 0)   return "Not proficient";
  if (mult === 0.5) return "Half proficiency";
  if (mult === 1)   return "Proficient";
  if (mult === 2)   return "Expertise";
  return `${mult}x proficiency`;
}

// ══════════════════════════════════════════════════════
// DICE
// ══════════════════════════════════════════════════════

async function rollVisible(actor, formula, flavor) {
  const roll = await new Roll(formula).evaluate();
  await roll.toMessage({ speaker: ChatMessage.getSpeaker({ actor }), flavor });
  return roll;
}

async function rollDie(actor, sides, flavor) {
  const roll = await rollVisible(actor, `1d${sides}`, flavor || `Rolling 1d${sides}`);
  return roll.total;
}

async function resolveCheck(actor, checkKey, ability, dc, extraBonus) {
  if (checkKey === "na") return null;
  const check = CHECK_DATA[checkKey];
  if (!check) throw new Error("Unknown check selected.");
  if (checkKey !== "none" && !check.abilities.includes(ability)) {
    throw new Error(`${check.label} can only use: ${check.abilities.map(a => a.toUpperCase()).join(" or ")}.`);
  }
  const abilityMod   = getAbilityMod(actor, ability);
  const profMult     = getProfMultiplier(actor, checkKey);
  const profApplied  = Math.floor(getProfBonus(actor) * profMult);
  const cleanExtra   = Number(extraBonus) || 0;
  const formula      = `1d20 + ${abilityMod} + ${profApplied} + ${cleanExtra}`;
  const flavor = `
    <strong>${safeText(actor.name)}: ${safeText(check.label)} (${ability.toUpperCase()})</strong><br>
    DC ${dc} | Ability ${abilityMod >= 0 ? "+" : ""}${abilityMod},
    Proficiency ${profApplied >= 0 ? "+" : ""}${profApplied},
    Extra ${cleanExtra >= 0 ? "+" : ""}${cleanExtra}
  `;
  const roll = await rollVisible(actor, formula, flavor);
  const d20 = roll.dice?.[0]?.results?.[0]?.result ?? "?";
  return {
    checkKey, checkLabel: check.label, type: check.type,
    ability, dc, d20, abilityMod, profMult, profApplied,
    extraBonus: cleanExtra, total: roll.total,
    success: roll.total >= dc, formula
  };
}

// ══════════════════════════════════════════════════════
// HTML RENDERING HELPERS
// ══════════════════════════════════════════════════════

function starIcons(count) {
  const n = Math.max(0, Number(count) || 0);
  if (n === 0) return `<span style="color:#999;">None</span>`;
  return "⭐".repeat(Math.min(n, 20)) + (n > 20 ? ` <strong>+${n - 20}</strong>` : "");
}

function progressBar(current, target, colour = "#c9a66b") {
  const c   = Math.max(0, Number(current) || 0);
  const t   = Math.max(1, Number(target)  || 1);
  const pct = Math.min(100, Math.round((c / t) * 100));
  return `
    <div style="border:1px solid #3a0000;border-radius:6px;overflow:hidden;height:16px;background:#0d0d0d;">
      <div style="height:16px;width:${pct}%;background:${colour};"></div>
    </div>
    <div style="font-size:12px;margin-top:3px;color:#aaa;">${c} / ${t} (${pct}%)</div>
  `;
}

const DM_BG_IMAGE = "https://i.imgur.com/WwkXkuk.png";
const DM_BG_STYLE = `background-image:url('${DM_BG_IMAGE}');background-size:cover;background-position:center;`;
const DM_OVERLAY  = `background:rgba(0,0,0,0.65);`;

function cardHeader(title, subtitle = "") {
  return `
    <div style="background:linear-gradient(90deg,rgba(10,0,0,0.88),rgba(20,0,0,0.85));padding:14px;border-bottom:2px solid #c9a66b;text-align:center;">
      <div style="font-size:22px;font-weight:bold;letter-spacing:2px;color:#c9a66b;text-shadow:0 0 8px rgba(201,166,75,0.5);">${title}</div>
      ${subtitle ? `<div style="font-size:16px;margin-top:4px;color:#ffffff;">${subtitle}</div>` : ""}
    </div>
  `;
}

function outerCard(title, subtitle, body) {
  return `
    <div style="border:2px solid #8b0000;border-radius:12px;overflow:hidden;${DM_BG_STYLE}color:#f0f0f0;box-shadow:0 0 24px rgba(139,0,0,0.5);font-family:'Signika',sans-serif;">
      ${cardHeader(title, subtitle)}
      <div style="${DM_OVERLAY}padding:14px;">${body}</div>
    </div>
  `;
}

function sectionBox(title, content, border = "#8b0000", bg = "rgba(0,0,0,0.42)", color = "#c9a66b") {
  return `
    <div style="border:1px solid ${border};border-radius:8px;padding:10px;margin-bottom:12px;background:${bg};">
      <div style="font-size:16px;font-weight:bold;color:${color};margin-bottom:8px;">${title}</div>
      <div style="color:#f0f0f0;">${content}</div>
    </div>
  `;
}

function actorOptionsHtml(actors) {
  return (actors || visibleActorsForUser())
    .map(a => `<option value="${a.id}">${safeText(a.name)}</option>`)
    .join("");
}

function activityOptionsHtml() {
  return Object.keys(ACTIVITY_DATA)
    .map(a => `<option value="${safeText(a)}">${safeText(a)}</option>`)
    .join("");
}

function checkOptionsHtml(actor) {
  return Object.entries(CHECK_DATA).map(([key, data]) => {
    const prof      = getProfMultiplier(actor, key);
    const abilities = data.abilities.map(a => a.toUpperCase()).join(" / ");
    const type      = key === "na" ? "N/A" : data.type === "skill" ? "Skill" : data.type === "tool" ? "Tool" : "Ability";
    return `<option value="${key}">${type}: ${safeText(data.label)} — ${abilities} — ${profText(prof)}</option>`;
  }).join("");
}

function abilityOptionsHtml(actor) {
  return ABILITIES.map(a => {
    const mod = getAbilityMod(actor, a);
    return `<option value="${a}">${a.toUpperCase()} (${mod >= 0 ? "+" : ""}${mod})</option>`;
  }).join("");
}

function rollBlockHtml(actor, n) {
  return `
    <div style="border:1px solid #8b0000;border-radius:6px;padding:10px;margin:8px 0;background:rgba(0,0,0,0.42);">
      <h3 style="color:#c9a66b;margin:0 0 8px;">Roll ${n}</h3>
      <label style="color:#aaa;font-size:13px;">Skill / Tool / Method</label>
      <select name="check${n}" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;">${checkOptionsHtml(actor)}</select>
      <br><br>
      <label style="color:#aaa;font-size:13px;">Ability</label>
      <select name="ability${n}" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;">${abilityOptionsHtml(actor)}</select>
      <br><br>
      <label style="color:#aaa;font-size:13px;">DC</label>
      <input name="dc${n}" type="number" value="10" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;">
    </div>
  `;
}

function hubButton(label, tool, gmOnly = false) {
  return `<button type="button" data-dt-tool="${tool}" data-gm-only="${gmOnly ? "1" : "0"}"
    style="margin:4px;padding:10px 14px;border-radius:6px;border:1px solid #c9a66b;background:#1a0000;color:#c9a66b;cursor:pointer;font-weight:bold;font-size:13px;transition:background 0.15s;"
    onmouseover="this.style.background='rgba(139,0,0,0.4)'"
    onmouseout="this.style.background='#1a0000'">${label}</button>`;
}

function checksHtml(checks) {
  return checks.map((c, i) => {
    if (c.noRoll) {
      return `<div style="padding:6px;margin-bottom:6px;border-left:4px solid #555;background:rgba(255,255,255,0.04);border-radius:4px;color:#aaa;">Roll ${i + 1}: No roll required.</div>`;
    }
    return `
      <div style="padding:8px;margin-bottom:8px;border-left:4px solid ${c.success ? "#c9a66b" : "#8b0000"};background:${c.success ? "rgba(0,0,0,0.35)" : "rgba(139,0,0,0.1)"};border-radius:4px;">
        <div style="font-weight:bold;color:#f0f0f0;">${safeText(c.checkLabel)} (${String(c.ability).toUpperCase()})</div>
        <div style="margin-top:4px;color:#aaa;">🎲 d20: <strong style="color:#f0f0f0;">${c.d20}</strong> + 🧠 ${c.abilityMod >= 0 ? "+" : ""}${c.abilityMod} + 🎓 ${c.profApplied >= 0 ? "+" : ""}${c.profApplied} + ✨ ${c.extraBonus >= 0 ? "+" : ""}${c.extraBonus}</div>
        <div style="margin-top:4px;font-size:15px;font-weight:bold;color:${c.success ? "#c9a66b" : "#e05050"};">Total: ${c.total} vs DC ${c.dc} — ${c.success ? "SUCCESS ✔" : "FAILURE ✖"}</div>
      </div>
    `;
  }).join("");
}

