async function openPlayerRequestDialog(actor) {
  if (!actor) return ui.notifications.warn("Select or choose a character first.");
  if (!game.user.isGM && !actor.isOwner) return ui.notifications.warn("You do not own this character.");

  const currentStars = getStars(actor);
  const dialog = new Dialog({
    title: `Submit Downtime Request: ${actor.name}`,
    content: `
      <form>
        <div style="width:720px;max-width:96vw;">
          ${outerCard("📨 Submit Downtime Request", safeText(actor.name), `
            <p><strong>Current Stars:</strong> ${currentStars} ${starIcons(currentStars)}</p>
            <label><strong>Activity</strong></label>
            <select name="activity" style="width:100%;">${activityOptionsHtml()}</select>
            <br><br>
            <label><strong>Short Request Summary</strong></label>
            <input name="summary" type="text" style="width:100%;" placeholder="Valen wants to craft a silvered reliquary using smith's tools.">
            <br><br>
            <label><strong>Proposed Check</strong></label>
            <select name="checkKey" style="width:100%;">${checkOptionsHtml(actor)}</select>
            <br><br>
            <label><strong>Ability</strong></label>
            <select name="ability" style="width:100%;">${abilityOptionsHtml(actor)}</select>
            <br><br>
            <label><strong>Requested Stars to Spend</strong></label>
            <input name="stars" type="number" value="1" min="0" style="width:100%;">
            <br><br>
            <label><strong>Time Spent</strong></label>
            <input name="timeSpent" type="text" style="width:100%;" placeholder="1 week, 3 days, between sessions, etc.">
            <br><br>
            <label><strong>Resources / Materials / Stake</strong></label>
            <textarea name="resources" rows="4" style="width:100%;"></textarea>
            <br><br>
            <label><strong>Details / Intent</strong></label>
            <textarea name="notes" rows="5" style="width:100%;"></textarea>
          `)}
        </div>
      </form>
    `,
    buttons: {
      submit: { label: "Submit Request to GM", callback: async (html) => {
          const form = html[0].querySelector("form");
          const request = {
            activity:  form.elements.activity.value,
            summary:   form.elements.summary.value,
            checkKey:  form.elements.checkKey.value,
            ability:   form.elements.ability.value,
            stars:     Number(form.elements.stars.value) || 0,
            timeSpent: form.elements.timeSpent.value,
            resources: form.elements.resources.value,
            notes:     form.elements.notes.value
          };
          await addRequest(actor, request);
          const saved = getRequests(actor).at(-1);
          await postChat(actor, requestCard(actor, saved), true);
          ui.notifications.info("Downtime request sent to the GM.");
        } },
      close: { label: "Close", callback: () => {} }
    },
    default: "submit"
  }, { width: 720 });
  dialog.render(true);
}

// ══════════════════════════════════════════════════════
// DIALOG: GM REQUEST DASHBOARD
// ══════════════════════════════════════════════════════

async function openGmRequestDashboard() {
  if (!game.user.isGM) return ui.notifications.warn("Only the GM can use this dashboard.");

  const pending    = allPendingRequests();
  const options    = pending.map((row, idx) =>
    `<option value="${idx}">${safeText(row.actor.name)} — ${safeText(row.request.activity)} — ${safeText(row.request.summary || "No summary")}</option>`
  ).join("");

  const listHtml = pending.length
    ? pending.map((row, idx) => {
        const req = row.request;
        const adj = req.adjudication;
        return `
          <div style="border:1px solid #8b0000;border-radius:10px;padding:10px;margin-bottom:10px;background:rgba(255,255,255,0.035);">
            <div style="font-size:17px;font-weight:bold;color:#c9a66b;">${idx + 1}. ${safeText(row.actor.name)} — ${safeText(req.activity)}</div>
            <div style="margin-top:6px;"><strong>Status:</strong> ${safeText(req.status || "Pending")}</div>
            <div><strong>Summary:</strong> ${safeText(req.summary || "No summary")}</div>
            <div><strong>Proposed Check:</strong> ${safeText(CHECK_DATA[req.checkKey]?.label || req.checkKey || "None")} ${req.ability ? `(${String(req.ability).toUpperCase()})` : ""}</div>
            <div><strong>Requested Stars:</strong> ${Number(req.stars) || 0}</div>
            <div><strong>Requested Time:</strong> ${safeText(req.timeSpent || "Not specified")}</div>
            <div><strong>Resources:</strong> ${safeText(req.resources || "None listed")}</div>
            <div><strong>Player Notes:</strong> ${safeText(req.notes || "None")}</div>
            ${adj ? `<div style="margin-top:6px;color:#c9a66b;"><strong>Existing GM Ruling:</strong> ${safeText(adj.status || "Adjudicated")} | Progress ${Number(adj.progressCurrent || 0)}/${Number(adj.progressTarget || 100)} ${safeText(adj.progressUnit || "progress")}</div>` : ""}
            <div style="margin-top:6px;font-size:12px;color:#cccccc;">Player: ${safeText(req.player || "Unknown")} | Date: ${safeText(new Date(req.date).toLocaleString())} | ID: ${safeText(req.id)}</div>
          </div>
        `;
      }).join("")
    : `<p>No pending downtime requests.</p>`;

  const dialog = new Dialog({
    title: "GM Downtime Request Dashboard",
    content: `
      <form>
        <div style="width:900px;max-width:96vw;max-height:82vh;overflow-y:auto;">
          ${outerCard("🧑‍⚖️ GM Downtime Adjudication", "Structured Request Response", `
            ${sectionBox("📨 Pending Request Queue", listHtml, "#8b0000", "rgba(0,0,0,0.42)", "#c9a66b")}
            <h2 style="color:#c9a66b;">GM Adjudication Panel</h2>
            <label><strong>Select Request</strong></label>
            <select name="reqIndex" style="width:100%;">${options}</select>
            <hr>
            <h3 style="color:#c9a66b;">Core Resolution</h3>
            <label><strong>GM Response / Ruling</strong></label>
            <textarea name="gmRuling" rows="4" style="width:100%;" placeholder="Explain what is approved, changed, denied, or required."></textarea>
            <br><br>
            <label><strong>Outcome Category</strong></label>
            <select name="outcomeCategory" style="width:100%;">
              <option value="Approved">Approved</option>
              <option value="Approved with Changes">Approved with Changes</option>
              <option value="Needs More Resources">Needs More Resources</option>
              <option value="Requires Quest / Scene">Requires Quest / Scene</option>
              <option value="Rejected">Rejected</option>
              <option value="Resolved Without Roll">Resolved Without Roll</option>
            </select>
            <br><br>
            <label><strong>Star Cost Override</strong></label>
            <input name="starCost" type="number" value="1" min="0" style="width:100%;">
            <br><br>
            <label><strong>DC Override</strong></label>
            <input name="dc" type="number" value="10" style="width:100%;">
            <br><br>
            <label><strong>Number of Rolls Required</strong></label>
            <select name="rollsRequired" style="width:100%;">
              <option value="0">0 — No roll required</option>
              <option value="1" selected>1 roll</option>
              <option value="2">2 rolls</option>
              <option value="3">3 rolls</option>
            </select>
            <hr>
            <h3 style="color:#c9a66b;">Progress Requirement</h3>
            <label><strong>Progress Completed</strong></label>
            <input name="progressCurrent" type="number" value="0" min="0" style="width:100%;">
            <br><br>
            <label><strong>Progress Required</strong></label>
            <input name="progressTarget" type="number" value="100" min="1" style="width:100%;">
            <br><br>
            <label><strong>Progress Unit</strong></label>
            <input name="progressUnit" type="text" value="progress" style="width:100%;" placeholder="progress, pages, recipe steps, item quality, research points, etc.">
            <br><br>
            <label><strong>Progress Gained on Success</strong></label>
            <input name="progressOnSuccess" type="number" value="25" style="width:100%;">
            <br><br>
            <label><strong>Progress Gained on Failure</strong></label>
            <input name="progressOnFailure" type="number" value="5" style="width:100%;">
            <hr>
            <h3 style="color:#c9a66b;">Time Requirement</h3>
            <label><strong>Time Already Spent</strong></label>
            <input name="timeCurrent" type="number" value="0" min="0" style="width:100%;">
            <br><br>
            <label><strong>Time Required</strong></label>
            <input name="timeTarget" type="number" value="1" min="0" style="width:100%;">
            <br><br>
            <label><strong>Time Unit</strong></label>
            <select name="timeUnit" style="width:100%;">
              <option value="days">days</option>
              <option value="weeks" selected>weeks</option>
              <option value="months">months</option>
              <option value="workweeks">workweeks</option>
              <option value="sessions">sessions</option>
              <option value="downtime phases">downtime phases</option>
            </select>
            <hr>
            <h3 style="color:#c9a66b;">Costs / Requirements</h3>
            <label><strong>Gold Cost</strong></label>
            <input name="goldCost" type="text" style="width:100%;" placeholder="Example: 250 gp, half item value, 50 gp per week">
            <br><br>
            <label><strong>Material / Resource Cost</strong></label>
            <textarea name="materialCost" rows="3" style="width:100%;" placeholder="Example: 2 dragon scales, 1 vial mimic ichor, silver reliquary frame"></textarea>
            <br><br>
            <label><strong>Spell Slots / Magic Required</strong></label>
            <textarea name="spellCost" rows="3" style="width:100%;" placeholder="Example: expend one 3rd-level spell slot each week"></textarea>
            <br><br>
            <label><strong>Tool / Proficiency Requirement</strong></label>
            <input name="toolRequirement" type="text" style="width:100%;" placeholder="Example: Smith's Tools proficiency, access to forge">
            <br><br>
            <label><strong>Location / Teacher / NPC / Faction Requirement</strong></label>
            <textarea name="externalRequirement" rows="3" style="width:100%;" placeholder="Example: Must work at temple forge; needs mentor"></textarea>
            <hr>
            <h3 style="color:#c9a66b;">GM Outcome Text</h3>
            <label><strong>Approved Result / Expected Reward</strong></label>
            <textarea name="approvedResult" rows="4" style="width:100%;" placeholder="What happens when this is completed?"></textarea>
            <br><br>
            <label><strong>Failure / Complication Notes</strong></label>
            <textarea name="failureNotes" rows="3" style="width:100%;" placeholder="What can go wrong? What complications are likely?"></textarea>
            <br><br>
            <label><strong>Stars to Award Immediately</strong></label>
            <input name="awardStars" type="number" value="0" style="width:100%;">
          `)}
        </div>
      </form>
    `,
    buttons: {
      resolve: { label: "Approve & Open Resolve Downtime", callback: async (html) => {
          if (!pending.length) return ui.notifications.warn("No pending requests.");
          const idx     = Number(html[0].querySelector("form").elements.reqIndex.value);
          const row     = pending[idx];
          const adj     = adjudicationFromForm(html[0].querySelector("form"));

          const updatedReqs = getRequests(row.actor).map(r =>
            r.id === row.request.id ? { ...r, status: "Approved for Resolution", adjudication: adj } : r
          );
          await setRequests(row.actor, updatedReqs);

          if (adj.awardStars !== 0) {
            const old = getStars(row.actor);
            await setStars(row.actor, Math.max(0, old + adj.awardStars));
            await addHistory(row.actor, {
              type: "Stars Awarded (Adjudication)",
              activity: row.request.activity,
              starsChange: adj.awardStars,
              totalAfter: getStars(row.actor),
              outcome: `Stars awarded during adjudication: ${adj.awardStars >= 0 ? "+" : ""}${adj.awardStars}`,
              notes: adj.gmRuling
            });
          }

          // Auto-sync into project/training tracker
          const approvedRequest = updatedReqs.find(r => r.id === row.request.id);
          if (approvedRequest) await syncRequest(row.actor, approvedRequest);

          await postChat(row.actor, gmAdjudicationCard(row.actor, row.request, adj), true);
          await openResolveDowntimeDialog(row.actor, { ...row.request, stars: adj.starCost, dc: adj.dc, adjudication: adj });
        } },
      approveOnly: { label: "Approve / Save Ruling Only", callback: async (html) => {
          if (!pending.length) return ui.notifications.warn("No pending requests.");
          const idx     = Number(html[0].querySelector("form").elements.reqIndex.value);
          const row     = pending[idx];
          const adj     = adjudicationFromForm(html[0].querySelector("form"));

          const updatedReqs = getRequests(row.actor).map(r =>
            r.id === row.request.id ? { ...r, status: adj.status, adjudication: adj } : r
          );
          await setRequests(row.actor, updatedReqs);

          if (adj.awardStars !== 0) {
            const old = getStars(row.actor);
            await setStars(row.actor, Math.max(0, old + adj.awardStars));
          }

          await addHistory(row.actor, {
            type: "Downtime Request Adjudicated",
            activity:    row.request.activity,
            starsChange: adj.awardStars,
            totalAfter:  getStars(row.actor),
            outcome:     adj.status,
            notes:       adj.gmRuling,
            adjudication: adj
          });

          // Auto-sync into project/training tracker
          const approvedRequest = updatedReqs.find(r => r.id === row.request.id);
          if (approvedRequest) await syncRequest(row.actor, approvedRequest);

          await postChat(row.actor, gmAdjudicationCard(row.actor, row.request, adj), true);
          ui.notifications.info(`${row.actor.name}'s downtime request adjudicated.`);
        } },
      reject: { label: "Reject Request", callback: async (html) => {
          if (!pending.length) return ui.notifications.warn("No pending requests.");
          const idx     = Number(html[0].querySelector("form").elements.reqIndex.value);
          const row     = pending[idx];
          const adj     = adjudicationFromForm(html[0].querySelector("form"));
          adj.status    = "Rejected";
          if (!adj.gmRuling) adj.gmRuling = "Rejected by GM.";

          const updatedReqs = getRequests(row.actor).map(r =>
            r.id === row.request.id ? { ...r, status: "Rejected", adjudication: adj } : r
          );
          await setRequests(row.actor, updatedReqs);

          await addHistory(row.actor, {
            type: "Downtime Request Rejected",
            activity:    row.request.activity,
            starsChange: 0,
            totalAfter:  getStars(row.actor),
            outcome:     "Rejected",
            notes:       adj.gmRuling,
            adjudication: adj
          });

          await postChat(row.actor, gmAdjudicationCard(row.actor, row.request, adj), true);
        } },
      close: { label: "Close", callback: () => {} }
    },
    default: "resolve"
  }, { width: 900 });

  dialog.render(true);
}


// ══════════════════════════════════════════════════════
// TRAINING COMPLETION — grant proficiency/language/reward
//
// On completion the macro applies the training outcome:
//  Language   → adds to actor's language traits (dnd5e)
//  Tool       → adds to actor's tool proficiencies
//  Combat     → adds armour/weapon proficiency or note
//  Ability    → posts a GM note (stat changes need DM approval)
//  Custom     → descriptive loot item summarising the achievement
// ══════════════════════════════════════════════════════

// dnd5e trait key maps
const LANGUAGE_KEY_MAP = {
  "common":"common","elvish":"elvish","dwarvish":"dwf","draconic":"draconic",
  "infernal":"infernal","celestial":"celestial","undercommon":"undercommon",
  "thieves' cant":"thieves","giant":"giant","gnomish":"gnome","halfling":"halfling",
  "orcish":"orc","abyssal":"abyssal","sylvan":"sylvan","deep speech":"deep"
};
const TOOL_KEY_MAP = {
  "thieves' tools":"thief","smith's tools":"smith","alchemist's supplies":"alchemist",
  "herbalism kit":"herb","calligrapher's supplies":"calligrapher",
  "cartographer's tools":"cart","cook's utensils":"cook",
  "woodcarver's tools":"woodcarver","leatherworker's tools":"leatherworker",
  "jeweler's tools":"jeweler","disguise kit":"disguise","forgery kit":"forgery",
  "navigator's tools":"navigator","poisoner's kit":"poisoner"
};

async function grantTrainingReward(actor, track) {
  const name     = track.name || "";
  const category = (track.category || track.trackerType || "").toLowerCase();
  const nameLow  = name.toLowerCase();
  const provNote = `<hr><p><em>Awarded on training completion — Downtime Master.</em></p>`;

  // Helper: add a key to a Set-valued trait — handles dnd5e v3 and v4 path differences
  async function addToTrait(traitPath, valueKey) {
    const raw = foundry.utils.getProperty(actor, `system.traits.${traitPath}`);
    let current;
    if (raw instanceof Set)              current = [...raw];
    else if (Array.isArray(raw))         current = [...raw];
    else if (raw?.value instanceof Set)  current = [...raw.value];
    else if (Array.isArray(raw?.value))  current = [...(raw.value)];
    else                                 current = [];

    if (current.includes(valueKey)) return false; // already proficient
    current.push(valueKey);

    // Try both path conventions used across dnd5e versions
    for (const path of [
      `system.traits.${traitPath}.value`,
      `system.traits.${traitPath}`
    ]) {
      try {
        const update = {}; update[path] = current;
        await actor.update(update);
        return true;
      } catch { /* try next */ }
    }
    return false;
  }

  async function postChat(emoji, title, text) {
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor }),
      content: outerCard(`${emoji} ${title}`, safeText(actor.name), `
        ${sectionBox("✔ Training Complete",
          `<strong style="color:#c9a66b;">${safeText(name)}</strong><br>
           <span style="color:#f0f0f0;">${text}</span>`,
          "#8b0000", "rgba(0,0,0,0.42)", "#c9a66b")}`)
    });
  }

  // ── Language ──────────────────────────────────────────
  if (category === "language") {
    const langKey = LANGUAGE_KEY_MAP[nameLow]
      ?? (nameLow.replace(/[^a-z0-9]/g, "").substring(0, 12) || "custom");
    try {
      await addToTrait("languages", langKey);
      await postChat("🗣", "Language Acquired", "Language proficiency added to your character sheet.");
      return { method: "language", name };
    } catch (err) { console.error("[Training] Language grant failed:", err); }
  }

  // ── Tool proficiency ──────────────────────────────────
  if (category === "tool") {
    const toolKey = TOOL_KEY_MAP[nameLow]
      ?? (nameLow.replace(/[^a-z0-9]/g, "").substring(0, 16) || "custom");
    try {
      // dnd5e v3 uses "toolProf", v4 uses "tool" — try both
      let ok = false;
      for (const path of ["toolProf", "tool"]) {
        try { const r = await addToTrait(path, toolKey); if (r !== false) { ok = true; break; } }
        catch { /* try next */ }
      }
      await postChat("🔧", "Tool Proficiency Acquired", "Tool proficiency added to your character sheet.");
      return { method: "tool", name };
    } catch (err) { console.error("[Training] Tool grant failed:", err); }
  }

  // ── Combat training ───────────────────────────────────
  if (category === "combat") {
    const nl = nameLow;
    let armorKey = null, weaponKey = null;
    if      (nl.includes("light armour")  || nl.includes("light armor"))  armorKey = "lgt";
    else if (nl.includes("medium armour") || nl.includes("medium armor")) armorKey = "med";
    else if (nl.includes("heavy armour")  || nl.includes("heavy armor"))  armorKey = "hvy";
    else if (nl.includes("shield"))                                        armorKey = "shl";
    else if (nl.includes("martial weapon"))                                weaponKey = "mar";

    let applied = false;
    if (armorKey)  { try { await addToTrait("armorProf",  armorKey);  applied = true; } catch (e) { console.error(e); } }
    if (weaponKey) { try { await addToTrait("weaponProf", weaponKey); applied = true; } catch (e) { console.error(e); } }

    if (applied) {
      await postChat("⚔", "Combat Training Complete", "Proficiency added to your character sheet.");
      return { method: "combat", name };
    }
  }

  // ── Ability Score training ────────────────────────────
  if (category === "ability score") {
    const statMap = { "strength":"str","dexterity":"dex","constitution":"con","intelligence":"int","wisdom":"wis","charisma":"cha" };
    const statKey = Object.entries(statMap).find(([k]) => nameLow.includes(k))?.[1];
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor }),
      content: outerCard("💪 Ability Score Training Complete", safeText(actor.name), `
        ${sectionBox("⚠ DM Action Required",
          `<strong style="color:#c9a66b;">${safeText(name)}</strong> is complete.<br><br>
           <span style="color:#f0f0f0;">Please apply the stat change manually on the character sheet.<br>
           <em style="color:#888;">Suggested: +1 to ${statKey?.toUpperCase() || "relevant stat"} (DM discretion).</em></span>`,
          "#8b0000", "rgba(0,0,0,0.42)", "#c9a66b")}`),
      whisper: ChatMessage.getWhisperRecipients("GM").map(u => u.id)
    });
    await actor.createEmbeddedDocuments("Item", [{
      name: `Training Complete: ${name}`, type: "loot",
      img: "https://assets.forge-vtt.com/65e70ddcf8447871c18a2b4d/macros/ChatGPT%20Image%20May%206%2C%202026%2C%2001_30_05%20PM.png",
      system: { quantity:1, weight:0, description:{ value:
        `<p><strong>Training Complete:</strong> ${safeText(name)}</p>
         <p>Qualifies for +1 ${statKey?.toUpperCase() || "ability score"} — DM approval required.</p>${provNote}` }}
    }]);
    return { method: "abilityNote", name };
  }

  // ── Fallback: certificate item ────────────────────────
  await actor.createEmbeddedDocuments("Item", [{
    name: `Training Certificate: ${name}`, type: "loot",
    img: "https://assets.forge-vtt.com/65e70ddcf8447871c18a2b4d/macros/ChatGPT%20Image%20May%206%2C%202026%2C%2001_30_05%20PM.png",
    system: { quantity:1, weight:0, description:{ value:
      `<p><strong>Training Completed:</strong> ${safeText(name)}</p>
       <p><strong>Category:</strong> ${safeText(track.category || "Custom")}</p>
       <p>${safeText(track.description || "")}</p>${provNote}` }}
  }]);
  return { method: "certificate", name };
}

// ══════════════════════════════════════════════════════
// CRAFTING COMPLETION — grant item to actor's inventory
//
// On completion the macro attempts (in order):
//  1. For scrolls: findScrollFromScribe / createScrollFromSpell
//  2. Compendium lookup by clean item name (MI-NNN suffix stripped)
//  3. Custom fully-described loot item built from project data
// ══════════════════════════════════════════════════════

function craftedItemNormalize(name) {
  return String(name)
    .toLowerCase()
    .replace(/\+/g, " plus ")
    .replace(/['']/g, "")
    .replace(/\s*\(MI-\d+\)\s*/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

async function findCraftedItemInCompendium(rawName) {
  const cleanName = rawName.replace(/\s*\(MI-\d+\)\s*/g, "").trim();
  const norm      = craftedItemNormalize(cleanName);
  const packs     = game.packs.filter(p => p.documentName === "Item");
  let   looseMatch = null;

  for (const pack of packs) {
    let index;
    try { index = await pack.getIndex({ fields: ["name","type","img","system.rarity"] }); }
    catch { continue; }

    let entry = index.find(i => craftedItemNormalize(i.name) === norm);
    if (entry) return await pack.getDocument(entry._id);

    if (!looseMatch) {
      entry = index.find(i => {
        const cn = craftedItemNormalize(i.name);
        return cn.startsWith(norm) || norm.startsWith(cn);
      });
      if (entry) looseMatch = { pack, entry };
    }
  }
  return looseMatch ? await looseMatch.pack.getDocument(looseMatch.entry._id) : null;
}

function buildCustomCraftedItem(project, actorName) {
  const rarityColour = {
    "Common": "#9d9d9d", "Uncommon": "#1eff00",
    "Rare": "#0070dd",   "Very Rare": "#a335ee",
    "Legendary": "#ff8000"
  };
  const rarity    = (project.rarity || "Common").replace(/\s*\(Skill\s*\d+\)/, "").trim();
  const colour    = rarityColour[rarity] || "#9d9d9d";
  const cleanName = project.name.replace(/\s*\(MI-\d+\)\s*/g, "").trim();

  return {
    name: cleanName,
    type: "loot",
    img:  "https://assets.forge-vtt.com/65e70ddcf8447871c18a2b4d/macros/ChatGPT%20Image%20May%206%2C%202026%2C%2001_30_05%20PM.png",
    system: {
      quantity: 1,
      weight:   0,
      rarity:   rarity.toLowerCase().replace(/\s+/g, ""),
      description: {
        value: `
          <p><strong style="color:${colour};">${safeText(rarity)} item — crafted by ${safeText(actorName || "unknown")}.</strong></p>
          <hr>
          <p><strong>Project:</strong> ${safeText(cleanName)}</p>
          ${project.tool     ? `<p><strong>Tool Affinity:</strong> ${safeText(project.tool)}</p>` : ""}
          ${project.goldCost ? `<p><strong>Gold Cost:</strong> ${safeText(project.goldCost)}</p>` : ""}
          ${project.materials? `<p><strong>Materials:</strong><br>${safeText(project.materials).replace(/\n/g,"<br>")}</p>` : ""}
          <hr>
          <p><strong>Properties:</strong></p>
          <p>${safeText(project.reward || "Custom crafted item.")}</p>
          <hr>
          <p><em>Hand-crafted via the Downtime Master. No standard compendium entry.</em></p>
        `
      }
    }
  };
}

async function grantCraftedItem(actor, project) {
  const rawName   = project.name;
  const cleanName = rawName.replace(/\s*\(MI-\d+\)\s*/g, "").trim();

  const provNote = `<hr><p><em>Crafted by <strong>${safeText(actor.name)}</strong> — Downtime Master.</em></p>`;

  // ── 1. Scroll ─────────────────────────────────────────
  if (cleanName.toLowerCase().includes("spell scroll")) {
    const scribeData = await findScrollFromScribe(null, cleanName);
    if (scribeData) {
      delete scribeData._id;
      scribeData.system = scribeData.system ?? {};
      scribeData.system.quantity = 1;
      scribeData.system.description = scribeData.system.description ?? {};
      scribeData.system.description.value = (scribeData.system.description.value ?? "") + provNote;
      await actor.createEmbeddedDocuments("Item", [scribeData]);
      return { method: "scribe", name: scribeData.name };
    }
    // Try createScrollFromSpell with a random spell at the right level
    const Item5e  = CONFIG?.Item?.documentClass;
    const lvlNum  = cleanName.match(/(\d+)(?:st|nd|rd|th)/i)?.[1];
    const lvl     = lvlNum ? Number(lvlNum) : cleanName.toLowerCase().includes("cantrip") ? "cantrip" : 1;
    const spells  = TREASURE_SPELLS[lvl];
    if (spells && typeof Item5e?.createScrollFromSpell === "function") {
      const randSpell = spells[Math.floor(Math.random() * spells.length)];
      try {
        for (const pack of game.packs.filter(p => p.documentName === "Item")) {
          const idx = await pack.getIndex({ fields: ["name","type"] });
          const entry = idx.find(i => i.type === "spell" &&
            i.name.toLowerCase() === randSpell.toLowerCase());
          if (entry) {
            const spellDoc = await pack.getDocument(entry._id);
            const scroll   = await Item5e.createScrollFromSpell(spellDoc, {}, { dialog: false });
            if (scroll) {
              const data = scroll.toObject();
              delete data._id;
              await actor.createEmbeddedDocuments("Item", [data]);
              return { method: "createScroll", name: data.name };
            }
          }
        }
      } catch { /* fall through */ }
    }
  }

  // ── 2. Compendium lookup ──────────────────────────────
  const compDoc = await findCraftedItemInCompendium(rawName);
  if (compDoc) {
    const data = compDoc.toObject();
    delete data._id;
    data.name = cleanName;
    data.system = data.system ?? {};
    data.system.quantity = 1;
    data.system.description = data.system.description ?? {};
    data.system.description.value = (data.system.description.value ?? "") + provNote;
    await actor.createEmbeddedDocuments("Item", [data]);
    return { method: "compendium", name: cleanName };
  }

  // ── 3. Custom loot item ───────────────────────────────
  const custom = buildCustomCraftedItem(project, actor.name);
  await actor.createEmbeddedDocuments("Item", [custom]);
  return { method: "custom", name: custom.name };
}

// ══════════════════════════════════════════════════════
// DIALOG: DOWNTIME PROJECT WORKBENCH (formerly Macro 2)
// ══════════════════════════════════════════════════════

async function openWorkbench(actor) {
  if (!actor) return ui.notifications.warn("Select a character first.");
  if (!game.user.isGM && !actor.isOwner) return ui.notifications.warn("You do not own this character.");

  const items = getAllWorkItems(actor).filter(i => !i.complete);
  if (!items.length) {
    return ui.notifications.warn(`${actor.name} has no active crafting projects or training tracks. Ask the GM to sync your approved requests first.`);
  }

  const currentStars = getStars(actor);
  const firstItem    = items[0];

  // Build the material consumption panel
  // Shows all actor-sheet material items (created by the engine) as checkboxes
  function materialConsumptionHtml() {
    const mats = getActorMaterialItems(actor);
    if (!mats.length) {
      return `<p style="color:#aaa;font-size:13px;">No tracked materials on sheet. Acquire materials via the Resource Ledger first.</p>`;
    }
    return mats.map(m => `
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;padding:6px 10px;border:1px solid #555;border-radius:6px;background:rgba(255,255,255,0.03);">
        <input type="checkbox" name="consumeMat_${safeText(m.flagKey)}" value="${safeText(m.name)}" style="width:16px;height:16px;flex-shrink:0;">
        <div style="flex:1;">
          <strong style="color:#c9a66b;">${safeText(m.name)}</strong>
          <span style="color:#aaa;font-size:12px;"> (${safeText(m.category)})</span>
        </div>
        <div style="display:flex;align-items:center;gap:6px;">
          <span style="color:#cccccc;font-size:13px;">Qty on sheet: <strong>${m.qty}</strong> — Consume:</span>
          <input type="number" name="consumeQty_${safeText(m.flagKey)}" value="1" min="1" max="${m.qty}"
            style="width:56px;padding:2px 4px;border-radius:4px;border:1px solid #777;background:#0d0d0d;color:#f0f0f0;text-align:center;">
        </div>
      </div>
    `).join("");
  }

  const dialog = new Dialog({
    title: `Downtime Project Workbench: ${actor.name}`,
    content: `
      <form>
        <div style="width:860px;max-width:96vw;max-height:82vh;overflow-y:auto;">
          ${outerCard("🛠 Downtime Project Workbench", safeText(actor.name), `
            <p><strong>Current Downtime Stars:</strong> ${currentStars} ${starIcons(currentStars)}</p>
            <label><strong>Select Project / Training Track</strong></label>
            <select name="workItem" style="width:100%;">${workItemOptionsHtml(actor)}</select>
            <br><br>
            <div data-dt-info>${itemInfoPanel(firstItem)}</div>
            <label><strong>Stars to Spend</strong></label>
            <input name="stars" type="number" value="0" min="0" style="width:100%;">
            <br><br>
            <label><strong>Progress on Success</strong></label>
            <input name="progressSuccess" type="number" value="25" style="width:100%;">
            <br><br>
            <label><strong>Progress on Failure</strong></label>
            <input name="progressFailure" type="number" value="5" style="width:100%;">
            <br><br>
            <label><strong>Extra Bonus / Penalty to Rolls</strong></label>
            <input name="extraBonus" type="number" value="0" style="width:100%;">
            ${rollBlockHtml(actor, 1)}
            ${rollBlockHtml(actor, 2)}
            ${rollBlockHtml(actor, 3)}

            ${sectionBox("🧪 Consume Materials from Sheet",
              `<p style="font-size:13px;color:#cccccc;margin-bottom:10px;">Check any materials being consumed in this work session. They will be removed from your character sheet and logged.</p>
               <div data-mat-consume-list>${materialConsumptionHtml()}</div>`,
              "#8b0000", "rgba(0,0,0,0.5)", "#c9a66b"
            )}

            <label><strong>Additional Cost Notes</strong></label>
            <textarea name="costNotes" rows="4" style="width:100%;" placeholder="Gold spent, spell slots, other costs…"></textarea>
            <br><br>
            <label><strong>Notes</strong></label>
            <textarea name="notes" rows="4" style="width:100%;"></textarea>
          `)}
        </div>
      </form>
    `,
    buttons: {
      work: { label: "Roll & Apply Progress", callback: async (html) => {
          const form        = html[0].querySelector("form");
          const compoundId  = form.elements.workItem.value;
          const { type, item } = getWorkItem(actor, compoundId);

          if (!item) return ui.notifications.warn("No project or training track selected.");

          const starsSpent      = Number(form.elements.stars.value)           || 0;
          const oldStars        = getStars(actor);

          if (starsSpent > oldStars) {
            return ui.notifications.warn(`${actor.name} only has ${oldStars} downtime star(s).`);
          }

          const progressSuccess = Number(form.elements.progressSuccess.value) || 0;
          const progressFailure = Number(form.elements.progressFailure.value) || 0;
          const extraBonus      = Number(form.elements.extraBonus.value)      || 0;
          const costNotes       = form.elements.costNotes.value;
          const notes           = form.elements.notes.value;

          // ── Gather checked materials to consume ──
          const toConsume = []; // [{ name, flagKey, qty }]
          const mats = getActorMaterialItems(actor);
          for (const m of mats) {
            const checkbox = form.elements[`consumeMat_${m.flagKey}`];
            if (checkbox?.checked) {
              const qtyInput = form.elements[`consumeQty_${m.flagKey}`];
              const qty      = Math.max(1, Number(qtyInput?.value) || 1);
              toConsume.push({ name: m.name, flagKey: m.flagKey, qty });
            }
          }

          let checks = [];
          try {
            for (let i = 1; i <= 3; i++) {
              const result = await resolveCheck(
                actor,
                form.elements[`check${i}`].value,
                form.elements[`ability${i}`].value,
                Number(form.elements[`dc${i}`].value),
                extraBonus
              );
              if (result) checks.push(result);
            }
          } catch (err) {
            return ui.notifications.warn(err.message);
          }

          if (!checks.length) {
            checks.push({ noRoll: true, checkLabel: "No roll required", total: 10, dc: 0, success: true });
          }

          const successes     = checks.filter(c => c.success).length;
          const failures      = checks.length - successes;
          const oldProgress   = Number(item.progress) || 0;
          const target        = Math.max(1, Number(item.target) || 100);
          const progressGained = (successes * progressSuccess) + (failures * progressFailure);

          item.progress = Math.min(target, Math.max(0, oldProgress + progressGained));
          item.complete = item.progress >= target;
          item.updated  = nowIso();

          if (item.adjudication) {
            item.adjudication.progressCurrent  = item.progress;
            item.adjudication.progressAfter    = item.progress;
            item.adjudication.progressComplete = item.complete;
            item.adjudication.progressGained   = progressGained;
          }

          if (type === "project") {
            const projects = getProjects(actor);
            const idx      = projects.findIndex(p => p.id === item.id);
            if (idx >= 0) projects[idx] = item;
            await setProjects(actor, projects);
          }
          if (type === "training") {
            const training = getTraining(actor);
            const idx      = training.findIndex(t => t.id === item.id);
            if (idx >= 0) training[idx] = item;
            await setTraining(actor, training);
          }

          const newStars = Math.max(0, oldStars - starsSpent);
          await setStars(actor, newStars);

          // ── Consume materials and build consumption log ──
          const consumptionLog = [];
          for (const c of toConsume) {
            const result = await consumeResourceItem(actor, c.name, c.qty);

            // Also decrement in flag ledger
            const resList = getResources(actor);
            const ledgerEntry = resList.find(r => r.name === c.name);
            if (ledgerEntry) {
              ledgerEntry.quantity = Math.max(0, (Number(ledgerEntry.quantity) || 0) - c.qty);
              ledgerEntry.updated  = nowIso();
              await setResources(actor, resList);
            }

            consumptionLog.push(
              result.success
                ? `${c.name} ×${c.qty} consumed${result.removed ? " (depleted)" : ` (${result.newQty} remaining)`}`
                : `${c.name} ×${c.qty} — not found on sheet (ledger decremented if present)`
            );
          }

          const allCostNotes = [
            ...consumptionLog,
            costNotes
          ].filter(Boolean).join("\n");

          // ── Grant completed item or training reward ──────────
          let grantResult = null;
          if (item.complete) {
            try {
              if (type === "project") {
                grantResult = await grantCraftedItem(actor, item);
              } else if (type === "training") {
                grantResult = await grantTrainingReward(actor, item);
              }
            } catch (err) {
              console.error("[Downtime] Completion grant failed:", err);
              grantResult = { method: "error", name: item.name };
            }
          }

          // Write history
          await addHistory(actor, {
            type:       type === "training" ? "Training Work" : "Crafting Project Work",
            activity:   item.name,
            starsChange: -starsSpent,
            totalAfter: newStars,
            checks,
            successes,
            avgTotal: Math.round(checks.reduce((s, c) => s + c.total, 0) / checks.length),
            outcome:  item.complete ? `Completed — ${grantResult?.method === "compendium" ? "official item granted" : grantResult?.method === "scribe" ? "scroll granted from Scribe" : grantResult?.method === "createScroll" ? "scroll created" : "custom item created"}` : `${oldProgress} → ${item.progress}/${item.target}`,
            resources: allCostNotes,
            notes
          });

          if (item.linkedRequestId) {
            const updatedReqs = getRequests(actor).map(r => {
              if (r.id !== item.linkedRequestId) return r;
              const updAdj = foundry.utils.deepClone(r.adjudication || {});
              updAdj.progressCurrent  = item.progress;
              updAdj.progressAfter    = item.progress;
              updAdj.progressComplete = item.complete;
              return { ...r, status: item.complete ? "Completed" : "Resolved / Progressed", adjudication: updAdj };
            });
            await setRequests(actor, updatedReqs);
          }

          // Build grant section for chat card
          const grantHtml = (item.complete && grantResult) ? sectionBox(
            type === "training" ? "🎓 Training Reward Granted" : "🎁 Item Granted",
            grantResult.method === "error"
              ? `<span style="color:#ff9c9c;">⚠ Grant encountered an error. Check the console.</span>`
              : `<div style="font-size:14px;color:#cccccc;">
                  <strong style="color:#c9a66b;">✔ ${safeText(grantResult.name)}</strong><br>
                  <span style="font-size:12px;color:#aaa;">
                    ${grantResult.method === "language"     ? "Language proficiency added to character sheet" :
                      grantResult.method === "tool"         ? "Tool proficiency added to character sheet" :
                      grantResult.method === "combat"       ? "Combat proficiency added to character sheet" :
                      grantResult.method === "abilityNote"  ? "⚠ Ability score training complete — DM approval required for stat increase" :
                      grantResult.method === "certificate"  ? "Training certificate added to inventory" :
                      grantResult.method === "compendium"   ? "Official item pulled from compendium" :
                      grantResult.method === "scribe"       ? "Spell scroll pulled from Spell Scroll Scribe" :
                      grantResult.method === "createScroll" ? "Spell scroll created from compendium spell" :
                      "Custom item created — no compendium match found"}
                  </span>
                </div>`,
            "#8b0000", "rgba(0,0,0,0.38)", "#c9a66b"
          ) : "";

          const consumptionHtml = consumptionLog.length
            ? sectionBox("🧪 Materials Consumed",
                `<ul>${consumptionLog.map(l => `<li>${safeText(l)}</li>`).join("")}</ul>`,
                "#8b0000", "rgba(0,0,0,0.42)", "#c9a66b"
              )
            : "";

          await postChat(actor, workbenchResultCard(actor, item, type, {
            checks, successes, failures, oldProgress, progressGained,
            starsSpent, starsRemaining: newStars, costNotes: allCostNotes, notes,
            consumptionHtml: consumptionHtml + grantHtml
          }));

          const grantNote = item.complete && grantResult
            ? ` Item "${grantResult.name}" added to inventory (${grantResult.method}).`
            : "";
          ui.notifications.info(`${item.name} updated: ${item.progress}/${item.target}.${consumptionLog.length ? ` ${consumptionLog.length} material(s) consumed.` : ""}${grantNote}`);
        } },
      close: { label: "Close", callback: () => {} }
    },
    default: "work"
  }, { width: 860 });

  dialog.render(true);

  setTimeout(() => {
    const form       = dialog.element[0]?.querySelector("form");
    if (!form) return;
    const workSelect = form.elements.workItem;
    const infoPanel  = dialog.element[0].querySelector("[data-dt-info]");

    function refresh() {
      const { item } = getWorkItem(actor, workSelect.value);
      if (!item) return;
      if (infoPanel) infoPanel.innerHTML = itemInfoPanel(item);
      applyWorkItemDefaults(actor, form, workSelect.value);
    }

    workSelect.addEventListener("change", refresh);
    refresh();
  }, 250);
}

// ══════════════════════════════════════════════════════
// DIALOG: CRAFTING TRACKER
// ══════════════════════════════════════════════════════

async function openCraftingTracker(actor, initialTab = "projects") {
  if (!actor) return ui.notifications.warn("Select a character first.");
  if (!game.user.isGM && !actor.isOwner) return ui.notifications.warn("You do not own this character.");

  // ── Tab styles ────────────────────────────────────────
  const TAB_ON  = "border-bottom:3px solid #c9a66b;color:#c9a66b;background:rgba(139,0,0,0.18);";
  const TAB_OFF = "border-bottom:3px solid transparent;color:#888;background:transparent;";
  const tabBtn  = (id, label, on) =>
    `<button type="button" data-tab="${id}" style="padding:9px 20px;border:none;border-radius:6px 6px 0 0;cursor:pointer;font-size:14px;font-weight:bold;${on ? TAB_ON : TAB_OFF}">${label}</button>`;

  // ── Blueprint catalogue helper (used in both build and filter) ───
  function buildBlueprintList(affFilter="All Affinities", rarFilter="All Rarities", search="") {
    const normSearch = search.toLowerCase().trim();
    const filtered = BLUEPRINT_CATALOGUE.filter(b =>
      (affFilter === "All Affinities" || b.affinity === affFilter) &&
      (rarFilter  === "All Rarities"  || b.rarity   === rarFilter)  &&
      (!normSearch || b.name.toLowerCase().includes(normSearch))
    );
    if (!filtered.length) return `<p style="color:#aaa;padding:12px;">No blueprints match the current filters.</p>`;
    const rc = { Common:"#9d9d9d",Uncommon:"#1eff00",Rare:"#0070dd","Very Rare":"#a335ee",Legendary:"#ff8000" };
    return filtered.map(b => `
      <div style="border:1px solid #3a3028;border-radius:8px;padding:12px;margin-bottom:8px;background:rgba(255,255,255,0.02);">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;flex-wrap:wrap;">
          <div>
            <div style="font-size:15px;font-weight:bold;color:#c9a66b;">${safeText(b.name)}</div>
            <div style="font-size:12px;color:#aaa;margin-top:2px;">
              ${safeText(b.affinity)} &nbsp;·&nbsp;
              <span style="color:${rc[b.rarity]||"#aaa"};">${safeText(b.rarity)}</span> &nbsp;·&nbsp;
              Skill ${b.skillLevel} &nbsp;·&nbsp; ${safeText(b.tool)} &nbsp;·&nbsp; DC ${b.dc}
            </div>
          </div>
          <div style="text-align:right;font-size:12px;color:#cccccc;white-space:nowrap;">
            ${progressBar(0, b.progressTarget, "#c9a66b")}
            +${b.progressPerSuccess} / +${b.progressPerFailure || 0} pts · ${safeText(b.timeEstimate)}
          </div>
        </div>
        <div style="font-size:12px;color:#cccccc;margin-top:6px;">${safeText(b.description)}</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;">
          <div>
            <div style="font-size:12px;font-weight:bold;color:#c9a66b;margin-bottom:2px;">📦 Materials</div>
            <ul style="font-size:12px;color:#cccccc;margin:0;padding-left:14px;">
              ${b.materials.map(m=>`<li>${m.qty}× ${safeText(m.name)} <span style="color:#888;">(${safeText(m.unit)})</span></li>`).join("")}
            </ul>
          </div>
          <div>
            <div style="font-size:12px;font-weight:bold;color:#c9a66b;margin-bottom:2px;">💰 ${safeText(b.goldCost)}</div>
            <div style="font-size:12px;color:#cccccc;margin-top:4px;">⭐ ${b.starCost}/session</div>
          </div>
        </div>
        <div style="margin-top:6px;padding:5px 8px;background:rgba(0,0,0,0.35);border:1px solid #4a7c52;border-radius:5px;font-size:12px;">
          <strong style="color:#c9a66b;">🏆 Reward:</strong> <span style="color:#cccccc;">${safeText(b.reward)}</span>
        </div>
        <div style="margin-top:6px;text-align:right;">
          <button type="button" data-quick-start="${safeText(b.name)}"
            style="padding:4px 14px;border-radius:5px;border:1px solid #c9a66b;background:rgba(0,0,0,0.60);color:#c9a66b;cursor:pointer;font-size:12px;font-weight:bold;">
            ➕ Start This Project
          </button>
        </div>
      </div>`).join("");
  }

  // ── Prepare panel HTML strings ────────────────────────
  const projects    = getProjects(actor);
  const projOptions = projects.map(p => `<option value="${p.id}">${safeText(p.name)} — ${p.progress}/${p.target}</option>`).join("");
  const projectList = projects.length
    ? projects.map(p => sectionBox(`🛠 ${safeText(p.name)}`,
        `${progressBar(p.progress, p.target, p.complete ? "#c9a66b" : "#c9a66b")}
         <strong>Status:</strong> ${p.complete ? "✅ Complete" : "⏳ In Progress"}<br>
         <strong>Rarity:</strong> ${safeText(p.rarity||"N/A")}<br>
         <strong>Tool:</strong> ${safeText(p.tool||"N/A")}<br>
         <strong>Materials:</strong> ${safeText(p.materials||"None")}<br>
         <strong>Reward:</strong> ${safeText(p.reward||"None")}`,
        p.complete?"#8b0000":"#8b0000",
        p.complete?"rgba(0,0,0,0.42)":"rgba(0,0,0,0.38)",
        p.complete?"#c9a66b":"#c9a66b"
      )).join("")
    : `<p style="color:#aaa;">No crafting projects yet. Start one from the Blueprints tab.</p>`;

  const allItems     = getAllWorkItems(actor).filter(i => !i.complete);
  const firstItem    = allItems[0];
  const currentStars = getStars(actor);

  const bpCatOpts = ["All Affinities",...BLUEPRINT_CATEGORIES]
    .map(c=>`<option>${safeText(c)}</option>`).join("");
  const bpRarOpts = ["All Rarities","Common","Uncommon","Rare","Very Rare","Legendary"]
    .map(r=>`<option>${safeText(r)}</option>`).join("");

  // ── Workbench panel HTML (mirrors standalone openWorkbench) ──
  function materialConsumptionHtml() {
    const mats = getActorMaterialItems(actor);
    if (!mats.length) return `<p style="color:#aaa;font-size:13px;">No tracked materials on sheet.</p>`;
    return mats.map(m => `
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;padding:6px 10px;border:1px solid #555;border-radius:6px;background:rgba(255,255,255,0.03);">
        <input type="checkbox" name="consumeMat_${safeText(m.flagKey)}" value="${safeText(m.name)}" style="width:16px;height:16px;flex-shrink:0;">
        <div style="flex:1;"><strong style="color:#c9a66b;">${safeText(m.name)}</strong>
          <span style="color:#aaa;font-size:12px;"> (${safeText(m.category)})</span></div>
        <div style="display:flex;align-items:center;gap:6px;">
          <span style="color:#cccccc;font-size:13px;">Qty: <strong>${m.qty}</strong> — Use:</span>
          <input type="number" name="consumeQty_${safeText(m.flagKey)}" value="1" min="1" max="${m.qty}"
            style="width:56px;border-radius:4px;border:1px solid #777;background:#0d0d0d;color:#f0f0f0;text-align:center;">
        </div>
      </div>`).join("");
  }

  const workbenchPanel = allItems.length ? `
    <p><strong>Current Stars:</strong> ${currentStars} ${starIcons(currentStars)}</p>
    <label><strong>Select Project / Track</strong></label>
    <select name="workItem" style="width:100%;margin-bottom:12px;">${workItemOptionsHtml(actor)}</select>
    <div data-dt-info style="margin-bottom:8px;">${firstItem ? itemInfoPanel(firstItem) : ""}</div>
    <label><strong>Stars to Spend</strong></label>
    <input name="stars" type="number" value="0" min="0" style="width:100%;"><br><br>
    <label><strong>Progress on Success</strong></label>
    <input name="progressSuccess" type="number" value="10" style="width:100%;"><br><br>
    <label><strong>Progress on Failure</strong></label>
    <input name="progressFailure" type="number" value="0" style="width:100%;"><br><br>
    <label><strong>Extra Bonus / Penalty</strong></label>
    <input name="extraBonus" type="number" value="0" style="width:100%;">
    ${rollBlockHtml(actor, 1)}
    ${rollBlockHtml(actor, 2)}
    ${rollBlockHtml(actor, 3)}
    ${sectionBox("🧪 Consume Materials",
      `<p style="font-size:13px;color:#cccccc;margin-bottom:8px;">Check materials consumed this session — they are removed from your sheet and logged.</p>
       <div data-mat-consume-list>${materialConsumptionHtml()}</div>`,
      "#8b0000","rgba(0,0,0,0.5)","#c9a66b"
    )}
    <label><strong>Cost Notes</strong></label>
    <textarea name="costNotes" rows="3" style="width:100%;" placeholder="Gold, spell slots, other costs…"></textarea><br><br>
    <label><strong>GM Notes</strong></label>
    <textarea name="notes" rows="3" style="width:100%;"></textarea>
  ` : `<p style="color:#aaa;text-align:center;padding:24px;">No active projects or training tracks.<br>Start a project from the <strong>Projects</strong> or <strong>Blueprints</strong> tab.</p>`;

  // ── Dialog ────────────────────────────────────────────
  const dialog = new Dialog({
    title: `🛠 Crafting: ${actor.name}`,
    content: `
      <form>
        <div style="width:880px;max-width:96vw;max-height:82vh;overflow-y:auto;display:flex;flex-direction:column;background-image:url('https://i.imgur.com/WwkXkuk.png');background-size:cover;background-position:center;border-radius:10px;overflow:hidden;">
          ${outerCard("🛠 Crafting", safeText(actor.name), `
            <!-- Tab bar -->
            <div style="display:flex;gap:2px;border-bottom:1px solid #1a0000;margin-bottom:16px;background:rgba(0,0,0,0.72);">
              ${tabBtn("projects",   "📋 Projects",   initialTab==="projects")}
              ${tabBtn("workbench",  "🔨 Workbench",  initialTab==="workbench")}
              ${tabBtn("blueprints", "📖 Blueprints",  initialTab==="blueprints")}
            </div>

            <!-- Projects panel -->
            <div data-panel="projects" style="display:${initialTab==="projects"?"block":"none"};overflow-y:auto;max-height:680px;padding-right:8px;">
              ${sectionBox("📋 Active Projects", projectList, "#8b0000","rgba(0,0,0,0.42)","#c9a66b")}
              <h3 style="color:#c9a66b;">✏️ Create New Project</h3>
              <label>Name</label>
              <input name="name" type="text" style="width:100%;" placeholder="e.g. Healing Feast Recipe"><br><br>
              <label>Progress Target</label>
              <input name="target" type="number" value="100" style="width:100%;"><br><br>
              <label>Starting Progress</label>
              <input name="start" type="number" value="0" style="width:100%;"><br><br>
              <label>Rarity / Complexity</label>
              <input name="rarity" type="text" style="width:100%;" placeholder="Common, Rare, Masterwork…"><br><br>
              <label>Required Tool</label>
              <input name="tool" type="text" style="width:100%;" placeholder="Smith's Tools, Cook's Utensils…"><br><br>
              <label>Required Materials</label>
              <textarea name="materials" rows="3" style="width:100%;"></textarea><br><br>
              <label>Completion Reward</label>
              <textarea name="reward" rows="3" style="width:100%;"></textarea><br><br>
              <label>Time Estimate</label>
              <input name="timeEstimate" type="text" style="width:100%;" placeholder="e.g. 1–2 work sessions"><br><br>
              <label>Gold Cost</label>
              <input name="goldCost" type="text" style="width:100%;" placeholder="e.g. ~25–50 gp">
              <hr>
              <h3 style="color:#c9a66b;">🔁 Manual Progress Update</h3>
              <label>Project</label>
              <select name="projectId" style="width:100%;">${projOptions||"<option value=''>None</option>"}</select><br><br>
              <label>Progress Change</label>
              <input name="progressChange" type="number" value="0" style="width:100%;"><br><br>
              <label>Update Note</label>
              <textarea name="updateNote" rows="2" style="width:100%;"></textarea>
            </div>

            <!-- Workbench panel -->
            <div data-panel="workbench" style="display:${initialTab==="workbench"?"block":"none"};overflow-y:auto;max-height:680px;padding-right:8px;">
              ${workbenchPanel}
            </div>

            <!-- Blueprints panel -->
            <div data-panel="blueprints" style="display:${initialTab==="blueprints"?"block":"none"};">
              <div style="display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:8px;align-items:end;margin-bottom:12px;">
                <div>
                  <label style="font-size:12px;color:#aaa;display:block;margin-bottom:3px;">Search</label>
                  <input name="bpSearch" type="text" style="width:100%;" placeholder="Item name…">
                </div>
                <div>
                  <label style="font-size:12px;color:#aaa;display:block;margin-bottom:3px;">Affinity</label>
                  <select name="bpAffFilter" style="width:100%;">${bpCatOpts}</select>
                </div>
                <div>
                  <label style="font-size:12px;color:#aaa;display:block;margin-bottom:3px;">Rarity</label>
                  <select name="bpRarFilter" style="width:100%;">${bpRarOpts}</select>
                </div>
                <button type="button" data-filter-bps
                  style="padding:7px 14px;border-radius:6px;border:1px solid #c9a66b;background:#1a0000;color:#c9a66b;cursor:pointer;font-weight:bold;">
                  🔍 Filter
                </button>
              </div>
              <div data-bp-list style="overflow-y:auto;max-height:560px;padding-right:4px;">
                ${buildBlueprintList()}
              </div>
            </div>
          `)}
        </div>
      </form>
    `,
    buttons: {
      work: { label: "🔨 Roll & Apply (Workbench)", callback: async (html) => {
          const form       = html[0].querySelector("form");
          const compoundId = form.elements.workItem?.value;
          if (!compoundId) return ui.notifications.warn("Switch to the Workbench tab and select a project first.");
          const { type, item } = getWorkItem(actor, compoundId);
          if (!item) return ui.notifications.warn("No project or training track selected.");

          const starsSpent      = Number(form.elements.stars?.value)           || 0;
          const progressSuccess = Number(form.elements.progressSuccess?.value)  || 10;
          const progressFailure = Number(form.elements.progressFailure?.value)  || 0;
          const extraBonus      = Number(form.elements.extraBonus?.value)       || 0;
          const costNotes       = form.elements.costNotes?.value?.trim()        || "";
          const notes           = form.elements.notes?.value?.trim()            || "";
          const oldStars        = getStars(actor);

          if (starsSpent > oldStars)
            return ui.notifications.warn(`Not enough stars (have ${oldStars}, need ${starsSpent}).`);

          // Resolve checks
          const checks = [];
          for (let i = 1; i <= 3; i++) {
            const checkKey = form.elements[`check${i}`]?.value;
            const dc       = Number(form.elements[`dc${i}`]?.value)      || 10;
            const ability  = form.elements[`ability${i}`]?.value         || "int";
            if (!checkKey || checkKey === "na") continue;
            try { checks.push(await resolveCheck(actor, checkKey, ability, dc, extraBonus)); }
            catch (err) { return ui.notifications.warn(err.message); }
          }
          if (!checks.length)
            checks.push({ noRoll:true, checkLabel:"No roll required", total:10, dc:0, success:true });

          const successes     = checks.filter(c => c.success).length;
          const failures      = checks.length - successes;
          const oldProgress   = Number(item.progress) || 0;
          const target        = Math.max(1, Number(item.target) || 100);
          const progressGained = (successes * progressSuccess) + (failures * progressFailure);

          item.progress = Math.min(target, Math.max(0, oldProgress + progressGained));
          item.complete = item.progress >= target;
          item.updated  = nowIso();

          if (item.adjudication) {
            item.adjudication.progressCurrent  = item.progress;
            item.adjudication.progressAfter    = item.progress;
            item.adjudication.progressComplete = item.complete;
            item.adjudication.progressGained   = progressGained;
          }

          if (type === "project") {
            const ps = getProjects(actor);
            const idx = ps.findIndex(p => p.id === item.id);
            if (idx >= 0) ps[idx] = item;
            await setProjects(actor, ps);
          } else {
            const ts = getTraining(actor);
            const idx = ts.findIndex(t => t.id === item.id);
            if (idx >= 0) ts[idx] = item;
            await setTraining(actor, ts);
          }

          await setStars(actor, Math.max(0, oldStars - starsSpent));

          // Material consumption
          const toConsume = [];
          const mats = getActorMaterialItems(actor);
          for (const m of mats) {
            const cb = form.elements[`consumeMat_${m.flagKey}`];
            if (cb?.checked) {
              const qty = Math.max(1, Number(form.elements[`consumeQty_${m.flagKey}`]?.value) || 1);
              toConsume.push({ name: m.name, qty });
            }
          }
          const consumptionLog = [];
          for (const c of toConsume) {
            const result = await consumeResourceItem(actor, c.name, c.qty);
            const resList = getResources(actor);
            const entry = resList.find(r => r.name === c.name);
            if (entry) {
              entry.quantity = Math.max(0, (Number(entry.quantity)||0) - c.qty);
              entry.updated  = nowIso();
              await setResources(actor, resList);
            }
            consumptionLog.push(result.success
              ? `${c.name} ×${c.qty} consumed${result.removed?" (depleted)":` (${result.newQty} remaining)`}`
              : `${c.name} ×${c.qty} — not on sheet`);
          }

          // Grant item or training reward on completion
          let grantResult = null;
          if (item.complete) {
            try {
              if (type === "project") {
                grantResult = await grantCraftedItem(actor, item);
              } else if (type === "training") {
                grantResult = await grantTrainingReward(actor, item);
              }
            } catch (err) { console.error("[Downtime Master]", err); }
          }

          const allCostNotes = [...consumptionLog, costNotes].filter(Boolean).join("\n");

          await addHistory(actor, {
            type: type === "training" ? "Training Work" : "Crafting Project Work",
            activity: item.name, starsChange: -starsSpent,
            totalAfter: getStars(actor), checks, successes,
            avgTotal: Math.round(checks.reduce((s,c)=>s+c.total,0)/checks.length),
            outcome: item.complete
              ? `Completed — ${
                  grantResult?.method === "compendium"   ? "official item granted" :
                  grantResult?.method === "scribe"       ? "scroll from Scribe" :
                  grantResult?.method === "createScroll" ? "scroll created" :
                  grantResult?.method === "language"     ? `language: ${grantResult.name}` :
                  grantResult?.method === "tool"         ? `tool proficiency: ${grantResult.name}` :
                  grantResult?.method === "combat"       ? `combat proficiency: ${grantResult.name}` :
                  grantResult?.method === "abilityNote"  ? "ability score training: DM approval required" :
                  grantResult?.method === "certificate"  ? "training certificate granted" :
                  "custom item"}`
              : `${oldProgress} → ${item.progress}/${target}`,
            resources: allCostNotes, notes
          });

          if (item.linkedRequestId) {
            const updReqs = getRequests(actor).map(r => {
              if (r.id !== item.linkedRequestId) return r;
              const upd = foundry.utils.deepClone(r.adjudication||{});
              upd.progressCurrent  = item.progress;
              upd.progressAfter    = item.progress;
              upd.progressComplete = item.complete;
              return { ...r, status: item.complete?"Completed":"Resolved / Progressed", adjudication: upd };
            });
            await setRequests(actor, updReqs);
          }

          const grantHtml = (item.complete && grantResult) ? sectionBox(
            type === "training" ? "🎓 Training Reward Granted" : "🎁 Item Granted",
            `<strong style="color:#c9a66b;">✔ ${safeText(grantResult.name)}</strong><br>
             <span style="font-size:12px;color:#aaa;">${
               grantResult.method === "language"     ? "Language proficiency added to character sheet" :
               grantResult.method === "tool"         ? "Tool proficiency added to character sheet" :
               grantResult.method === "combat"       ? "Combat proficiency added to character sheet" :
               grantResult.method === "abilityNote"  ? "⚠ Ability score training complete — DM approval required for stat increase" :
               grantResult.method === "certificate"  ? "Training certificate added to inventory" :
               grantResult.method === "compendium"   ? "Official item from compendium" :
               grantResult.method === "scribe"       ? "Scroll from Spell Scroll Scribe" :
               grantResult.method === "createScroll" ? "Scroll created from spell" :
               "Custom item created"
             }</span>`,
            "#8b0000","rgba(0,0,0,0.38)","#c9a66b"
          ) : "";

          const consumptionHtml = consumptionLog.length
            ? sectionBox("🧪 Materials Consumed",
                `<ul>${consumptionLog.map(l=>`<li>${safeText(l)}</li>`).join("")}</ul>`,
                "#8b0000","rgba(0,0,0,0.42)","#c9a66b")
            : "";

          await postChat(actor, workbenchResultCard(actor, item, type, {
            checks, successes, failures, oldProgress, progressGained,
            starsSpent, starsRemaining: getStars(actor),
            costNotes: allCostNotes, notes,
            consumptionHtml: consumptionHtml + grantHtml
          }));

          ui.notifications.info(`${item.name}: ${item.progress}/${target}.${item.complete?" ✅ Complete!":""}`);
        } },
      save: { label: "💾 Save Project", callback: async (html) => {
          const form = html[0].querySelector("form");
          const f    = form.elements;

          // Create new project
          if (f.name?.value?.trim()) {
            const project = {
              id: uid("proj"), name: f.name.value.trim(),
              progress: Number(f.start?.value)||0,
              target: Math.max(1, Number(f.target?.value)||100),
              rarity: f.rarity?.value||"", tool: f.tool?.value||"",
              materials: f.materials?.value||"", reward: f.reward?.value||"",
              timeEstimate: f.timeEstimate?.value||"", goldCost: f.goldCost?.value||"",
              created: nowIso(), complete: false
            };
            const list = getProjects(actor);
            list.push(project);
            await setProjects(actor, list);
            await addHistory(actor, {
              type:"Crafting Project Created", activity: project.name,
              starsChange:0, totalAfter:getStars(actor),
              outcome:`Project created: 0/${project.target}`,
              resources: project.materials, notes: project.reward
            });
            await postChat(actor, simpleUpdateCard("🛠 Project Created", safeText(actor.name), [{
              title:`📋 ${safeText(project.name)}`,
              content:`${progressBar(0,project.target)}<br>
                <strong>Tool:</strong> ${safeText(project.tool)}<br>
                <strong>Time:</strong> ${safeText(project.timeEstimate||"Not specified")}<br>
                <strong>Cost:</strong> ${safeText(project.goldCost||"Not specified")}`
            }]));
            ui.notifications.info(`Project "${project.name}" created.`);
          }

          // Manual progress update
          const projId = f.projectId?.value;
          const change = Number(f.progressChange?.value)||0;
          if (projId && change !== 0) {
            const ps = getProjects(actor);
            const p  = ps.find(x => x.id === projId);
            if (p) {
              const old  = Number(p.progress)||0;
              p.progress = Math.max(0, old + change);
              p.complete = p.progress >= p.target;
              await setProjects(actor, ps);
              await addHistory(actor, {
                type:"Crafting Project Update", activity: p.name,
                starsChange:0, totalAfter:getStars(actor),
                outcome:`${old} → ${p.progress}/${p.target}`,
                notes: f.updateNote?.value||""
              });
              await postChat(actor, simpleUpdateCard("🛠 Project Updated", safeText(actor.name), [{
                title: p.name,
                content:`${progressBar(p.progress, p.target, p.complete?"#c9a66b":"#c9a66b")}<br>
                  <strong>Change:</strong> ${change>=0?"+":""}${change}<br>
                  <strong>Note:</strong> ${safeText(f.updateNote?.value||"None")}`
              }]));
              if (p.complete) ui.notifications.info(`${p.name} is now complete!`);
            }
          }
        } },
      close: { label: "Close", callback: () => {} }
    },
    default: "work"
  }, { width: 880 });

  dialog.render(true);

  setTimeout(() => {
    const el = dialog.element[0];
    if (!el) return;
    const form = el.querySelector("form");

    // ── Tab switching ─────────────────────────────────
    el.querySelectorAll("[data-tab]").forEach(btn => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.tab;
        el.querySelectorAll("[data-tab]").forEach(b => {
          const on = b.dataset.tab === id;
          b.style.cssText = `padding:9px 20px;border:none;border-radius:6px 6px 0 0;cursor:pointer;font-size:14px;font-weight:bold;${on?"border-bottom:3px solid #c9a66b;color:#c9a66b;background:rgba(139,0,0,0.18);":"border-bottom:3px solid transparent;color:#888;background:transparent;"}`;
        });
        el.querySelectorAll("[data-panel]").forEach(p => {
          p.style.display = p.dataset.panel === id ? "block" : "none";
        });
      });
    });

    // ── Workbench: item selector → info panel refresh ─
    const workSel   = form?.elements?.workItem;
    const infoPanel = el.querySelector("[data-dt-info]");
    if (workSel && infoPanel) {
      workSel.addEventListener("change", () => {
        const { item } = getWorkItem(actor, workSel.value);
        if (!item) return;
        infoPanel.innerHTML = itemInfoPanel(item);
        applyWorkItemDefaults(actor, form, workSel.value);
      });
      // Apply defaults for first item
      if (workSel.value) applyWorkItemDefaults(actor, form, workSel.value);
    }

    // ── Blueprint: filter + quick-start ──────────────
    const bpListEl  = el.querySelector("[data-bp-list]");

    function refreshBpList() {
      if (!bpListEl) return;
      const aff    = form?.elements?.bpAffFilter?.value || "All Affinities";
      const rar    = form?.elements?.bpRarFilter?.value || "All Rarities";
      const search = form?.elements?.bpSearch?.value    || "";
      bpListEl.innerHTML = buildBlueprintList(aff, rar, search);
      bindQuickStart();
    }

    function bindQuickStart() {
      el.querySelectorAll("[data-quick-start]").forEach(btn => {
        btn.addEventListener("click", async () => {
          const bpName = btn.dataset.quickStart;
          const bp = BLUEPRINT_CATALOGUE.find(b => b.name === bpName);
          if (!bp) return;
          const list = getProjects(actor);
          if (list.some(p => p.name === bp.name && !p.complete))
            return ui.notifications.warn(`"${bp.name}" is already an active project.`);
          const project = {
            id: uid("proj"), name: bp.name,
            progress:0, target: bp.progressTarget,
            rarity:`${bp.rarity} (Skill ${bp.skillLevel})`,
            tool: bp.tool,
            materials: bp.materials.map(m=>`${m.qty}× ${m.name} (${m.unit})`).join("\n"),
            reward: bp.reward, timeEstimate: bp.timeEstimate, goldCost: bp.goldCost,
            blueprintRef: bp.name, created: nowIso(), complete:false,
            dc: bp.dc, rollsRequired:1,
            progressOnSuccess: bp.progressPerSuccess,
            progressOnFailure: bp.progressPerFailure,
            checkKey: bp.checkKey, ability: bp.ability, starCost: bp.starCost
          };
          list.push(project);
          await setProjects(actor, list);
          await addHistory(actor, {
            type:"Crafting Project Created (Blueprint)", activity: bp.name,
            starsChange:0, totalAfter:getStars(actor),
            outcome:`Blueprint started: 0/${bp.progressTarget}`,
            notes:`${bp.affinity} | ${bp.rarity} | Skill ${bp.skillLevel} | Est. ${bp.timeEstimate}`
          });
          await postChat(actor, outerCard("📖 Blueprint Started", safeText(actor.name), `
            ${sectionBox(`🛠 ${safeText(bp.name)}`,
              `<strong>Affinity:</strong> ${safeText(bp.affinity)}<br>
               <strong>Rarity:</strong> ${safeText(bp.rarity)}<br>
               <strong>Skill Level:</strong> ${bp.skillLevel}<br>
               <strong>DC:</strong> ${bp.dc}<br>
               ${progressBar(0, bp.progressTarget, "#c9a66b")}<br>
               <strong>Est. Time:</strong> ${safeText(bp.timeEstimate)}`,
              "#8b0000","rgba(0,0,0,0.38)","#c9a66b"
            )}`
          ));
          ui.notifications.info(`"${bp.name}" added to Projects. Go to the Workbench tab to begin rolling.`);
        });
      });
    }

    el.querySelector("[data-filter-bps]")?.addEventListener("click", refreshBpList);
    // Live search on Enter/input
    form?.elements?.bpSearch?.addEventListener("keydown", e => { if (e.key === "Enter") refreshBpList(); });
    bindQuickStart();

  }, 300);
}

