const TRAINING_CATEGORIES = [...new Set(TRAINING_PRESETS.map(t => t.category))];

async function openTrainingTracker(actor) {
  if (!actor) return ui.notifications.warn("Select a character first.");
  if (!game.user.isGM && !actor.isOwner) return ui.notifications.warn("You do not own this character.");

  const tracks      = getTraining(actor);
  const catOptions  = ["All", ...TRAINING_CATEGORIES].map(c=>`<option>${safeText(c)}</option>`).join("");
  const trackOptions = tracks.map(t=>`<option value="${t.id}">${safeText(t.name)} — ${t.progress}/${t.target}</option>`).join("");

  function buildPresetList(catFilter="All") {
    const list = catFilter==="All" ? TRAINING_PRESETS : TRAINING_PRESETS.filter(p=>p.category===catFilter);
    return list.map(p=>`
      <div style="border:1px solid #1a0000;border-radius:8px;padding:10px;margin-bottom:8px;background:rgba(0,0,0,0.4);">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:6px;">
          <div>
            <div style="font-size:15px;font-weight:bold;color:#f0f0f0;">${safeText(p.name)}</div>
            <div style="font-size:12px;color:#8b0000;margin-top:1px;">
              ${safeText(p.category)} &nbsp;·&nbsp; DC ${p.dc} &nbsp;·&nbsp; ${safeText(p.checkKey?.toUpperCase())} check
            </div>
          </div>
          <div style="text-align:right;font-size:12px;color:#aaa;white-space:nowrap;">
            ${p.progressTarget} pts total<br>${safeText(p.timeEstimate)}
          </div>
        </div>
        <div style="font-size:12px;color:#cccccc;margin-top:6px;">${safeText(p.description)}</div>
        ${p.limitations?.length ? `<div style="font-size:11px;color:#888;margin-top:4px;font-style:italic;">${p.limitations.map(l=>safeText(l)).join(" · ")}</div>` : ""}
        <div style="text-align:right;margin-top:6px;">
          <button type="button" data-start-training="${safeText(p.name)}"
            style="padding:3px 12px;border-radius:5px;border:1px solid #c9a66b;background:rgba(0,0,0,0.60);color:#c9a66b;cursor:pointer;font-size:12px;font-weight:bold;">
            ➕ Start Training
          </button>
        </div>
      </div>`).join("");
  }

  const trackListHtml = tracks.length
    ? tracks.map(t=>sectionBox(`🎓 ${safeText(t.name)}`,
        `${progressBar(t.progress, t.target, t.complete?"#c9a66b":"#8b0000")}
         <strong>Category:</strong> ${safeText(t.category||"N/A")}<br>
         <strong>Status:</strong> ${t.complete?"✅ Complete":"⏳ In Progress"}<br>
         <strong>Time Estimate:</strong> ${safeText(t.timeEstimate||"N/A")}`,
        t.complete?"#8b0000":"#8b0000",
        t.complete?"rgba(0,0,0,0.42)":"rgba(139,0,0,0.08)",
        t.complete?"#c9a66b":"#e05050"
      )).join("")
    : `<p style="color:#aaa;">No training tracks yet. Use the presets below or create a custom track.</p>`;

  const dialog = new Dialog({
    title: `🎓 Training: ${actor.name}`,
    content: `<form>
      <div style="width:900px;max-width:96vw;background-image:url('https://i.imgur.com/WwkXkuk.png');background-size:cover;background-position:center;border:1px solid #8b0000;border-radius:10px;padding:0;max-height:82vh;overflow-y:auto;">
        <div style="background:linear-gradient(135deg,#1a0000,#0d0d0d);border-bottom:2px solid #8b0000;padding:14px 20px;display:flex;align-items:center;gap:12px;">
          <span style="font-size:22px;">🎓</span>
          <div><div style="font-size:18px;font-weight:bold;color:#c9a66b;letter-spacing:1px;">Training</div>
          <div style="font-size:12px;color:#888;">${safeText(actor.name)}</div></div>
        </div>
        <div style="padding:16px 16px 0;display:flex;gap:2px;border-bottom:1px solid #1a0000;background:rgba(0,0,0,0.72);">
          <button type="button" data-tab="tracks" style="flex:1;padding:8px;border:none;border-bottom:3px solid #8b0000;background:rgba(139,0,0,0.15);color:#e05050;cursor:pointer;font-weight:bold;">📋 Active Tracks</button>
          <button type="button" data-tab="presets" style="flex:1;padding:8px;border:none;border-bottom:3px solid transparent;background:transparent;color:#888;cursor:pointer;font-weight:bold;">📚 Training Presets</button>
          <button type="button" data-tab="custom"  style="flex:1;padding:8px;border:none;border-bottom:3px solid transparent;background:transparent;color:#888;cursor:pointer;font-weight:bold;">✏️ Custom Track</button>
        </div>
        <div style="padding:16px;background:rgba(0,0,0,0.65);">
          <div data-panel="tracks">${trackListHtml}</div>
          <div data-panel="presets" style="display:none;">
            <div style="display:flex;gap:8px;margin-bottom:12px;align-items:end;">
              <div style="flex:1;">
                <label style="font-size:11px;color:#888;display:block;margin-bottom:3px;">Category</label>
                <select name="trainingCatFilter" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;">${catOptions}</select>
              </div>
              <button type="button" data-filter-training
                style="padding:7px 14px;border-radius:6px;border:1px solid #8b0000;background:rgba(139,0,0,0.2);color:#e05050;cursor:pointer;font-weight:bold;">🔍 Filter</button>
            </div>
            <div data-training-preset-list>${buildPresetList()}</div>
          </div>
          <div data-panel="custom" style="display:none;">
            <h3 style="color:#c9a66b;margin-top:0;">✏️ Custom Training Track</h3>
            <label style="color:#aaa;font-size:13px;">Track Name</label>
            <input name="name" type="text" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;" placeholder="e.g. Infernal Language Study"><br>
            <label style="color:#aaa;font-size:13px;">Category</label>
            <input name="category" type="text" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;" placeholder="Language, Tool, Combat…"><br>
            <label style="color:#aaa;font-size:13px;">Progress Target</label>
            <input name="target" type="number" value="250" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"><br>
            <label style="color:#aaa;font-size:13px;">DC</label>
            <input name="dc" type="number" value="13" style="width:60px;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"><br>
            <label style="color:#aaa;font-size:13px;">Time Estimate</label>
            <input name="timeEstimate" type="text" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;" placeholder="e.g. 25+ sessions"><br>
            <label style="color:#aaa;font-size:13px;">Description / Outcome</label>
            <textarea name="description" rows="3" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"></textarea>
            <hr style="border-color:#1a0000;">
            <h3 style="color:#c9a66b;">🔁 Update Track</h3>
            <label style="color:#aaa;font-size:13px;">Track</label>
            <select name="trackId" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;">${trackOptions||"<option value=''>None</option>"}</select><br>
            <label style="color:#aaa;font-size:13px;">Progress Change</label>
            <input name="progressChange" type="number" value="0" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"><br>
            <label style="color:#aaa;font-size:13px;">Note</label>
            <textarea name="updateNote" rows="2" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;"></textarea>
          </div>
        </div>
      </div>
    </form>`,
    buttons: {
      save: { label: "💾 Save / Create", callback: async (html) => {
        const f = html[0].querySelector("form").elements;
        if (f.name?.value?.trim()) {
          const t = { id:uid("trn"), name:f.name.value.trim(), category:f.category?.value||"Custom",
            progress:0, target:Math.max(1,Number(f.target?.value)||250),
            dc:Number(f.dc?.value)||13, timeEstimate:f.timeEstimate?.value||"",
            description:f.description?.value||"", created:nowIso(), complete:false,
            progressOnSuccess:10, progressOnFailure:0 };
          const list = getTraining(actor); list.push(t); await setTraining(actor, list);
          await addHistory(actor,{type:"Training Started",activity:t.name,starsChange:0,totalAfter:getStars(actor),outcome:`0/${t.target}`});
          ui.notifications.info(`Training track "${t.name}" started.`);
        }
        const tid = f.trackId?.value; const chg = Number(f.progressChange?.value)||0;
        if (tid && chg !== 0) {
          const ts = getTraining(actor); const t = ts.find(x=>x.id===tid);
          if (t) { const old=Number(t.progress)||0; t.progress=Math.max(0,old+chg); t.complete=t.progress>=t.target; await setTraining(actor,ts);
            await addHistory(actor,{type:"Training Update",activity:t.name,starsChange:0,totalAfter:getStars(actor),outcome:`${old}→${t.progress}/${t.target}`,notes:f.updateNote?.value||""});
            if(t.complete) ui.notifications.info(`${t.name} training complete!`); }
        }
      } },
      close: { label: "Close", callback: () => {} }
    },
    default: "save"
  }, { width: 900 });
  dialog.render(true);
  setTimeout(() => {
    const el = dialog.element[0];
    if (!el) return;
    const form = el.querySelector("form");
    el.querySelectorAll("[data-tab]").forEach(btn => btn.addEventListener("click", () => {
      const id = btn.dataset.tab;
      el.querySelectorAll("[data-tab]").forEach(b => {
        const on = b.dataset.tab===id;
        b.style.cssText=`flex:1;padding:8px;border:none;cursor:pointer;font-weight:bold;${on?"border-bottom:3px solid #8b0000;background:rgba(139,0,0,0.15);color:#e05050;":"border-bottom:3px solid transparent;background:transparent;color:#888;"}`;
      });
      el.querySelectorAll("[data-panel]").forEach(p => p.style.display=p.dataset.panel===id?"block":"none");
    }));
    const presetList = el.querySelector("[data-training-preset-list]");
    el.querySelector("[data-filter-training]")?.addEventListener("click",()=>{
      const cat = form?.elements?.trainingCatFilter?.value||"All";
      if(presetList) presetList.innerHTML=buildPresetList(cat);
      bindStartTraining();
    });
    function bindStartTraining() {
      el.querySelectorAll("[data-start-training]").forEach(btn => btn.addEventListener("click", async () => {
        const p = TRAINING_PRESETS.find(x=>x.name===btn.dataset.startTraining);
        if (!p) return;
        const list = getTraining(actor);
        if (list.some(t=>t.name===p.name&&!t.complete)) return ui.notifications.warn(`"${p.name}" already active.`);
        const t = {id:uid("trn"),name:p.name,category:p.category,progress:0,target:p.progressTarget,
          dc:p.dc,checkKey:p.checkKey,ability:p.ability,tool:p.tool,timeEstimate:p.timeEstimate,
          description:p.description,limitations:p.limitations||[],created:nowIso(),complete:false,
          progressOnSuccess:p.successPer??10,progressOnFailure:p.failPer??0};
        list.push(t); await setTraining(actor,list);
        await addHistory(actor,{type:"Training Started (Preset)",activity:p.name,starsChange:0,totalAfter:getStars(actor),outcome:`0/${p.progressTarget}`,notes:p.description});
        ui.notifications.info(`"${p.name}" training started. Go to Workbench to roll progress.`);
      }));
    }
    bindStartTraining();
  }, 300);
}

async function openResourceLedger(actor) {
  if (!actor) return ui.notifications.warn("Select a character first.");
  if (!game.user.isGM && !actor.isOwner) return ui.notifications.warn("You do not own this character.");

  const catFilterOptions = ["All", ...MATERIAL_CATEGORIES]
    .map(c => `<option value="${safeText(c)}">${safeText(c)}</option>`).join("");

  // Multi-add: show a filtered catalogue as checkboxes with quantity inputs.
  // Filters by category AND by name/source/use search term simultaneously.
  function buildCatalogueTable(catFilter="All", searchTerm="") {
    const q = searchTerm.trim().toLowerCase();
    const items = MATERIAL_CATALOGUE.filter(m => {
      if (catFilter !== "All" && m.category !== catFilter) return false;
      if (q) {
        return (m.name   || "").toLowerCase().includes(q) ||
               (m.source || "").toLowerCase().includes(q) ||
               (m.use    || "").toLowerCase().includes(q) ||
               (m.category || "").toLowerCase().includes(q);
      }
      return true;
    });
    if (!items.length) return `<p style="color:#aaa;padding:8px;">No items match — try a different search or category.</p>`;
    // Use the global MATERIAL_CATALOGUE index as the field name — always safe,
    // avoids apostrophes/brackets/slashes in names breaking querySelector.
    return `<div style="display:grid;gap:4px;">` + items.map(m => {
      const idx = MATERIAL_CATALOGUE.indexOf(m);
      return `
      <div style="display:flex;align-items:center;gap:8px;padding:5px 8px;border:1px solid #1a0000;border-radius:5px;background:rgba(0,0,0,0.3);">
        <input type="checkbox" name="addMat_${idx}" data-mat-idx="${idx}" style="width:14px;height:14px;flex-shrink:0;">
        <div style="flex:1;min-width:0;">
          <div style="font-size:13px;color:#f0f0f0;font-weight:bold;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${safeText(m.name)}</div>
          <div style="font-size:11px;color:#8b0000;">${safeText(m.category)}${m.source ? ` · ${safeText(m.source)}` : ""}</div>
        </div>
        <input type="number" name="qty_${idx}" value="1" min="1"
          style="width:56px;background:#111;border:1px solid #333;color:#c9a66b;padding:4px;border-radius:4px;text-align:center;font-weight:bold;">
      </div>`;
    }).join("") + `</div>`;
  }

  const resources = getResources(actor);
  const resourceListHtml = resources.length
    ? resources.map(r => `
        <div style="display:flex;align-items:center;justify-content:space-between;padding:6px 10px;border:1px solid #1a0000;border-radius:6px;margin-bottom:6px;background:rgba(0,0,0,0.4);">
          <div>
            <span style="font-size:14px;color:#f0f0f0;font-weight:bold;">${safeText(r.name)}</span>
            <span style="font-size:11px;color:#8b0000;margin-left:6px;">${safeText(r.category||"")}</span>
          </div>
          <div style="display:flex;align-items:center;gap:10px;">
            <span style="font-size:16px;font-weight:bold;color:#c9a66b;">${Number(r.quantity)||0}</span>
            <span style="font-size:11px;color:#666;">${safeText(r.unit||"unit")}</span>
          </div>
        </div>`).join("")
    : `<p style="color:#aaa;font-size:13px;">No resources tracked yet. Use the Add tab to add materials.</p>`;

  const dialog = new Dialog({
    title: `📦 Resources: ${actor.name}`,
    content: `<form>
      <div style="width:900px;max-width:96vw;background-image:url('https://i.imgur.com/WwkXkuk.png');background-size:cover;background-position:center;border:1px solid #8b0000;border-radius:10px;max-height:82vh;overflow-y:auto;">
        <div style="background:linear-gradient(135deg,#1a0000,#0d0d0d);border-bottom:2px solid #8b0000;padding:14px 20px;display:flex;align-items:center;gap:12px;">
          <span style="font-size:22px;">📦</span>
          <div><div style="font-size:18px;font-weight:bold;color:#c9a66b;">Resource Ledger</div>
          <div style="font-size:12px;color:#888;">${safeText(actor.name)}</div></div>
        </div>
        <div style="padding:16px 16px 0;display:flex;gap:2px;border-bottom:1px solid #1a0000;">
          <button type="button" data-tab="stock" style="flex:1;padding:8px;border:none;border-bottom:3px solid #8b0000;background:rgba(139,0,0,0.15);color:#e05050;cursor:pointer;font-weight:bold;">📋 Current Stock</button>
          <button type="button" data-tab="add"   style="flex:1;padding:8px;border:none;border-bottom:3px solid transparent;background:transparent;color:#888;cursor:pointer;font-weight:bold;">➕ Add Resources</button>
          <button type="button" data-tab="use"   style="flex:1;padding:8px;border:none;border-bottom:3px solid transparent;background:transparent;color:#888;cursor:pointer;font-weight:bold;">🔻 Use Resources</button>
        </div>
        <div style="padding:16px;background:rgba(0,0,0,0.65);">
          <div data-panel="stock">${resourceListHtml}</div>
          <div data-panel="add" style="display:none;">
            <div style="display:grid;grid-template-columns:1fr 1fr auto;gap:8px;margin-bottom:10px;align-items:end;">
              <div>
                <label style="font-size:11px;color:#888;display:block;margin-bottom:3px;">Search by name, source or use</label>
                <input name="matSearch" type="text" placeholder="e.g. Troll, venom, crystal…"
                  style="width:100%;background:#111;border:1px solid #8b0000;color:#f0f0f0;padding:6px;border-radius:4px;">
              </div>
              <div>
                <label style="font-size:11px;color:#888;display:block;margin-bottom:3px;">Filter by Category</label>
                <select name="catFilter" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;">${catFilterOptions}</select>
              </div>
              <button type="button" data-filter-cat
                style="padding:7px 14px;border-radius:6px;border:1px solid #8b0000;background:rgba(139,0,0,0.2);color:#e05050;cursor:pointer;font-weight:bold;white-space:nowrap;">🔍 Filter</button>
            </div>
            <p style="font-size:12px;color:#888;margin-bottom:8px;">Check items to add and set quantities. Click <strong style="color:#c9a66b;">Add Selected</strong> below.</p>
            <div data-mat-list>${buildCatalogueTable()}</div>
          </div>
          <div data-panel="use" style="display:none;">
            <p style="font-size:13px;color:#aaa;margin-bottom:12px;">Select a resource and specify how much to use (removes from stock).</p>
            <label style="color:#aaa;font-size:13px;">Resource</label>
            <select name="useResourceName" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;">
              ${resources.map(r=>`<option value="${safeText(r.name)}">${safeText(r.name)} (${Number(r.quantity)||0} ${safeText(r.unit||"unit")})</option>`).join("")||"<option>No resources</option>"}
            </select>
            <label style="color:#aaa;font-size:13px;">Quantity to Use</label>
            <input name="useQty" type="number" value="1" min="1"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"><br>
            <label style="color:#aaa;font-size:13px;">Reason / Note</label>
            <input name="useNote" type="text" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;" placeholder="Used in crafting, sold, consumed…">
          </div>
        </div>
      </div>
    </form>`,
    buttons: {
      add: { label: "➕ Add Selected", callback: async (html) => {
        const form = html[0].querySelector("form");
        const res  = getResources(actor);
        let added  = 0;
        for (let idx = 0; idx < MATERIAL_CATALOGUE.length; idx++) {
          const cb = form.querySelector(`[name="addMat_${idx}"]`);
          if (!cb?.checked) continue;
          const m   = MATERIAL_CATALOGUE[idx];
          if (!m) continue;
          const qtyInput = form.querySelector(`[name="qty_${idx}"]`);
          const qty = Math.max(1, Number(qtyInput?.value) || 1);

          // Update the ledger flag
          const existing = res.find(r => r.name === m.name);
          if (existing) {
            existing.quantity = (Number(existing.quantity) || 0) + qty;
            existing.updated  = nowIso();
          } else {
            res.push({ id: uid("res"), name: m.name, category: m.category,
                       unit: m.unit || "unit", quantity: qty, created: nowIso() });
          }

          // Create / update the loot item directly on the actor's sheet
          {
            const flagKey  = `dtMaterial_${m.name.replace(/\s+/g, "_")}`;
            const existing = actor.items.find(i =>
              i.getFlag(MODULE_SCOPE, "dtMaterialKey") === flagKey);
            if (existing) {
              await existing.update({ "system.quantity": (existing.system.quantity ?? 1) + qty });
            } else {
              await actor.createEmbeddedDocuments("Item", [{
                name: m.name,
                type: "loot",
                img: "https://assets.forge-vtt.com/65e70ddcf8447871c18a2b4d/macros/ChatGPT%20Image%20May%206%2C%202026%2C%2001_30_05%20PM.png",
                system: {
                  description: { value:
                    `<p><strong>Category:</strong> ${m.category}</p>
                     <p><strong>Source:</strong> ${m.source || "Various"}</p>
                     <p><strong>Use:</strong> ${m.use || ""}</p>
                     <p><strong>Value:</strong> ${m.value || "—"}</p>
                     <p><strong>Rarity:</strong> ${m.rarity || "Common"}${m.edible ? " [Edible]" : ""}</p>
                     <p><em>Tracked by the Downtime Master.</em></p>` },
                  quantity: qty, weight: 0,
                  price: { value: 0, denomination: "gp" },
                  rarity: (m.rarity || "common").toLowerCase().replace(/\s+/g, ""),
                  identified: true
                },
                flags: {
                  [MODULE_SCOPE]: {
                    dtMaterialKey: flagKey,
                    dtCategory: m.category, dtSource: m.source,
                    dtEdible: m.edible,     dtValue: m.value,
                    dtRarity: m.rarity
                  }
                }
              }]);
            }
          }

          added++;
        }
        if (!added) return ui.notifications.warn("No items checked.");
        await setResources(actor, res);
        await addHistory(actor, { type:"Resources Added", activity:`${added} material type(s)`,
          starsChange:0, totalAfter:getStars(actor), outcome:`Added to ledger` });
        ui.notifications.info(`Added ${added} resource type(s) to ${actor.name}'s ledger and inventory.`);
      } },
      use: { label: "🔻 Use Resource", callback: async (html) => {
        const f = html[0].querySelector("form").elements;
        const name = f.useResourceName?.value; const qty = Math.max(1,Number(f.useQty?.value)||1);
        if (!name) return ui.notifications.warn("No resource selected.");
        const res = getResources(actor); const r = res.find(x=>x.name===name);
        if (!r) return ui.notifications.warn("Resource not found.");
        const old = Number(r.quantity)||0;
        r.quantity = Math.max(0, old-qty); r.updated = nowIso();
        await setResources(actor, res);
        await addHistory(actor,{type:"Resource Used",activity:name,starsChange:0,totalAfter:getStars(actor),outcome:`${old}→${r.quantity}`,notes:f.useNote?.value||""});
        ui.notifications.info(`${name}: ${old} → ${r.quantity}`);
      } },
      close: { label: "Close", callback: () => {} }
    },
    default: "add"
  }, { width: 900 });
  dialog.render(true);
  setTimeout(() => {
    const el = dialog.element[0];
    if (!el) return;
    const form = el.querySelector("form");
    el.querySelectorAll("[data-tab]").forEach(btn => btn.addEventListener("click", () => {
      const id = btn.dataset.tab;
      el.querySelectorAll("[data-tab]").forEach(b => {
        const on = b.dataset.tab===id;
        b.style.cssText=`flex:1;padding:8px;border:none;cursor:pointer;font-weight:bold;${on?"border-bottom:3px solid #8b0000;background:rgba(139,0,0,0.15);color:#e05050;":"border-bottom:3px solid transparent;background:transparent;color:#888;"}`;
      });
      el.querySelectorAll("[data-panel]").forEach(p=>p.style.display=p.dataset.panel===id?"block":"none");
    }));
    const matList = el.querySelector("[data-mat-list]");
    function refreshMatList() {
      const cat    = form?.elements?.catFilter?.value  || "All";
      const search = form?.elements?.matSearch?.value  || "";
      if (matList) matList.innerHTML = buildCatalogueTable(cat, search);
    }
    el.querySelector("[data-filter-cat]")?.addEventListener("click", refreshMatList);
    // Also trigger on Enter in the search box and after a short debounce on input
    let searchTimer;
    form?.elements?.matSearch?.addEventListener("keydown", e => {
      if (e.key === "Enter") { e.preventDefault(); refreshMatList(); }
    });
    form?.elements?.matSearch?.addEventListener("input", () => {
      clearTimeout(searchTimer);
      searchTimer = setTimeout(refreshMatList, 280);
    });
  }, 300);
}

async function openRelationTracker(actor) {
  if (!actor) return ui.notifications.warn("Select a character first.");
  if (!game.user.isGM && !actor.isOwner) return ui.notifications.warn("You do not own this character.");

  // Score bar: gold to the right for positive, red to the left for negative
  function scorebar(score) {
    const s   = Math.max(-100, Math.min(100, Number(score) || 0));
    const pct = Math.abs(s) / 2; // max 50% from centre
    const col = s < 0 ? "#8b0000" : "#c9a66b";
    const label = s === 0 ? "Neutral" : s > 0 ? `+${s}` : `${s}`;
    const labelCol = s < 0 ? "#e05050" : s > 0 ? "#c9a66b" : "#888";
    return `
      <div style="margin:4px 0 2px;">
        <div style="width:100%;height:10px;background:#1a1a1a;border-radius:6px;border:1px solid #2a2a2a;position:relative;overflow:hidden;">
          ${s !== 0 ? `<div style="position:absolute;${s<0?"right":"left"}:50%;width:${pct}%;height:100%;background:${col};border-radius:${s<0?"4px 0 0 4px":"0 4px 4px 0"};"></div>` : ""}
          <div style="position:absolute;left:50%;top:0;width:1px;height:100%;background:#444;"></div>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:10px;color:#555;margin-top:1px;">
          <span>Hostile −100</span>
          <span style="color:${labelCol};font-weight:bold;">${label}</span>
          <span>Allied +100</span>
        </div>
      </div>`;
  }

  // Build merged list: all FR factions + any saved custom/scored ones
  // FR factions that have saved data use the saved score; unsaved ones show 0
  function buildMergedFactions() {
    const saved = getRelations(actor);
    const savedById = {};
    for (const r of saved) savedById[r.id] = r;

    // FR presets — use saved score if it exists
    const frList = FR_FACTIONS.map(f => {
      const id    = "fr_" + f.name.replace(/\W+/g, "_");
      const saved = savedById[id];
      return saved
        ? { ...f, ...saved, id }
        : { ...f, id, score: 0, status: "Neutral" };
    });

    // Custom relations not in FR_FACTIONS
    const frNames = new Set(FR_FACTIONS.map(f => f.name));
    const custom  = saved.filter(r => !frNames.has(r.name));

    const all = [...frList, ...custom];

    // Non-zero scores first (sorted by absolute value descending),
    // then neutrals (score === 0) alphabetically below.
    all.sort((a, b) => {
      const as = Math.abs(Number(a.score) || 0);
      const bs = Math.abs(Number(b.score) || 0);
      if (as !== bs) return bs - as;           // higher absolute score first
      return a.name.localeCompare(b.name);     // alpha within same score
    });

    return all;
  }

  function buildFactionListHtml(factions) {
    if (!factions.length) return `<p style="color:#aaa;">No factions.</p>`;
    return factions.map(r => `
      <div style="border:1px solid #1a0000;border-radius:8px;padding:10px;margin-bottom:8px;background:rgba(0,0,0,0.4);">
        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:4px;">
          <div>
            <div style="font-size:14px;font-weight:bold;color:#f0f0f0;">${safeText(r.name)}</div>
            <div style="font-size:11px;color:#666;">${safeText(r.type||"Faction")}${r.region?` · ${safeText(r.region)}`:""}</div>
          </div>
          <div style="font-size:12px;color:${Number(r.score||0)>=0?"#c9a66b":"#e05050"};">
            ${safeText(r.status||"Neutral")}
          </div>
        </div>
        ${scorebar(r.score || 0)}
        ${r.notes ? `<div style="font-size:11px;color:#aaa;margin-top:4px;font-style:italic;">${safeText(r.notes)}</div>` : ""}
      </div>`).join("");
  }

  function buildFactionOptions(factions) {
    return factions.map(r =>
      `<option value="${safeText(r.id)}">${safeText(r.name)} (${Number(r.score||0)>=0?"+":""}${Number(r.score||0)})</option>`
    ).join("");
  }

  const initialFactions = buildMergedFactions();

  const dialog = new Dialog({
    title: `🤝 Factions & Relations: ${actor.name}`,
    content: `<form>
      <div style="width:820px;max-width:96vw;background-image:url('https://i.imgur.com/WwkXkuk.png');background-size:cover;background-position:center;border:1px solid #8b0000;border-radius:10px;max-height:82vh;overflow-y:auto;">
        <div style="background:linear-gradient(135deg,#1a0000,#0d0d0d);border-bottom:2px solid #8b0000;padding:14px 20px;display:flex;align-items:center;gap:12px;">
          <span style="font-size:22px;">🤝</span>
          <div>
            <div style="font-size:18px;font-weight:bold;color:#c9a66b;">Factions &amp; Relations</div>
            <div style="font-size:12px;color:#888;">${safeText(actor.name)} · Forgotten Realms + Custom</div>
          </div>
        </div>
        <div style="padding:0 16px;display:flex;gap:2px;border-bottom:1px solid #1a0000;padding-top:12px;background:rgba(0,0,0,0.72);">
          <button type="button" data-tab="list"   style="flex:1;padding:8px;border:none;border-bottom:3px solid #8b0000;background:rgba(139,0,0,0.15);color:#e05050;cursor:pointer;font-weight:bold;">📋 All Factions</button>
          <button type="button" data-tab="update" style="flex:1;padding:8px;border:none;border-bottom:3px solid transparent;background:transparent;color:#888;cursor:pointer;font-weight:bold;">⚖️ Adjust Score</button>
          <button type="button" data-tab="add"    style="flex:1;padding:8px;border:none;border-bottom:3px solid transparent;background:transparent;color:#888;cursor:pointer;font-weight:bold;">➕ Custom Faction</button>
        </div>
        <div style="padding:16px;background:rgba(0,0,0,0.65);">

          <!-- List panel — rebuilt live after every update -->
          <div data-panel="list">
            <p style="font-size:12px;color:#555;margin-bottom:10px;">Gold bar = allied/positive &nbsp;·&nbsp; Red bar = hostile/negative &nbsp;·&nbsp; Range: −100 to +100</p>
            <div data-faction-list>${buildFactionListHtml(initialFactions)}</div>
          </div>

          <!-- Update panel -->
          <div data-panel="update" style="display:none;">
            <p style="font-size:13px;color:#aaa;margin-bottom:12px;">Select a faction and apply a score change. Positive values = more allied, negative = more hostile.</p>
            <label style="color:#aaa;font-size:13px;">Faction</label>
            <select name="factionId" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;">
              ${buildFactionOptions(initialFactions)}
            </select><br>
            <label style="color:#aaa;font-size:13px;">Score Change</label>
            <input name="scoreChange" type="number" value="5"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"><br>
            <label style="color:#aaa;font-size:13px;">New Status (leave blank to keep current)</label>
            <input name="newStatus" type="text" placeholder="Ally, Neutral, Hostile, Rival, Patron…"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"><br>
            <label style="color:#aaa;font-size:13px;">Reason / Note</label>
            <textarea name="reason" rows="3"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:12px;"></textarea>
            <button type="button" data-apply-score
              style="width:100%;padding:10px;border-radius:6px;border:1px solid #c9a66b;background:rgba(201,166,75,0.15);color:#c9a66b;cursor:pointer;font-size:14px;font-weight:bold;">
              ⚖️ Apply Score Change
            </button>
            <div data-update-feedback style="margin-top:8px;font-size:13px;color:#c9a66b;min-height:20px;"></div>
          </div>

          <!-- Add custom panel -->
          <div data-panel="add" style="display:none;">
            <h3 style="color:#c9a66b;margin-top:0;">➕ Add Custom Faction / NPC</h3>
            <label style="color:#aaa;font-size:13px;">Name</label>
            <input name="addName" type="text"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"
              placeholder="Temple of Torm, Black Market Guild, Reya Mantlemorn…"><br>
            <label style="color:#aaa;font-size:13px;">Type</label>
            <input name="addType" type="text"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"
              placeholder="Temple, Criminal Faction, NPC, Guild…"><br>
            <label style="color:#aaa;font-size:13px;">Region / Location</label>
            <input name="addRegion" type="text"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"><br>
            <label style="color:#aaa;font-size:13px;">Starting Score</label>
            <input name="addScore" type="number" value="0"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"><br>
            <label style="color:#aaa;font-size:13px;">Status</label>
            <input name="addStatus" type="text"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"
              placeholder="Ally, Neutral, Rival…"><br>
            <label style="color:#aaa;font-size:13px;">Notes</label>
            <textarea name="addNotes" rows="3"
              style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:12px;"></textarea>
            <button type="button" data-add-faction
              style="width:100%;padding:10px;border-radius:6px;border:1px solid #c9a66b;background:rgba(0,0,0,0.40);color:#c9a66b;cursor:pointer;font-size:14px;font-weight:bold;">
              ➕ Add Faction
            </button>
            <div data-add-feedback style="margin-top:8px;font-size:13px;color:#c9a66b;min-height:20px;"></div>
          </div>
        </div>
      </div>
    </form>`,
    buttons: {
      close: { label: "Close", callback: () => {} }
    },
    default: "close"
  }, { width: 820 });

  dialog.render(true);

  setTimeout(() => {
    const el = dialog.element[0];
    if (!el) return;
    const form = el.querySelector("form");

    // ── Helpers ───────────────────────────────────────
    function refreshList() {
      const factions   = buildMergedFactions();
      const listEl     = el.querySelector("[data-faction-list]");
      const factionSel = form?.elements?.factionId;
      if (listEl)     listEl.innerHTML     = buildFactionListHtml(factions);
      if (factionSel) factionSel.innerHTML = buildFactionOptions(factions);
    }

    function feedback(selector, msg, colour="#c9a66b") {
      const el2 = el.querySelector(selector);
      if (!el2) return;
      el2.style.color = colour;
      el2.textContent = msg;
      setTimeout(() => { el2.textContent = ""; }, 3000);
    }

    // ── Tab switching ─────────────────────────────────
    el.querySelectorAll("[data-tab]").forEach(btn => btn.addEventListener("click", () => {
      const id = btn.dataset.tab;
      el.querySelectorAll("[data-tab]").forEach(b => {
        const on = b.dataset.tab === id;
        b.style.cssText = `flex:1;padding:8px;border:none;cursor:pointer;font-weight:bold;${on ? "border-bottom:3px solid #8b0000;background:rgba(139,0,0,0.15);color:#e05050;" : "border-bottom:3px solid transparent;background:transparent;color:#888;"}`;
      });
      el.querySelectorAll("[data-panel]").forEach(p =>
        p.style.display = p.dataset.panel === id ? "block" : "none"
      );
      if (id === "list") refreshList(); // always fresh when switching to list
    }));

    // ── Apply score change ────────────────────────────
    el.querySelector("[data-apply-score]")?.addEventListener("click", async () => {
      const f      = form?.elements;
      const fid    = f?.factionId?.value;
      const change = Number(f?.scoreChange?.value) || 0;
      if (!fid)    return feedback("[data-update-feedback]", "Select a faction first.", "#e05050");
      if (!change) return feedback("[data-update-feedback]", "Score change is 0 — nothing to apply.", "#e05050");

      const list = getRelations(actor);
      let rel    = list.find(r => r.id === fid || r.name === fid);

      if (!rel) {
        // First time scoring a FR preset — create the saved entry
        const fr = FR_FACTIONS.find(x => ("fr_" + x.name.replace(/\W+/g, "_")) === fid);
        if (!fr) return feedback("[data-update-feedback]", "Faction not found.", "#e05050");
        rel = { id: fid, name: fr.name, type: fr.type, region: fr.region,
                score: 0, status: "Neutral", created: nowIso() };
        list.push(rel);
      }

      const old   = Number(rel.score) || 0;
      rel.score   = Math.max(-100, Math.min(100, old + change));
      const newStatus = f?.newStatus?.value?.trim();
      if (newStatus) rel.status = newStatus;
      rel.updated = nowIso();

      await setRelations(actor, list);
      await addHistory(actor, {
        type: "Faction Score Changed", activity: rel.name,
        starsChange: 0, totalAfter: getStars(actor),
        outcome: `${old} → ${rel.score}`,
        notes: f?.reason?.value || ""
      });
      await postChat(actor, simpleUpdateCard("🤝 Faction Updated", safeText(actor.name), [{
        title: safeText(rel.name),
        content: `<strong>Change:</strong> ${change >= 0 ? "+" : ""}${change}<br>
                  <strong>Score:</strong> ${old} → <strong>${rel.score}</strong><br>
                  <strong>Status:</strong> ${safeText(rel.status)}`
      }]));

      // Refresh the list panel immediately so bars update
      refreshList();
      feedback("[data-update-feedback]", `✔ ${rel.name}: ${old} → ${rel.score}`, "#c9a66b");
    });

    // ── Add custom faction ────────────────────────────
    el.querySelector("[data-add-faction]")?.addEventListener("click", async () => {
      const f = form?.elements;
      const name = f?.addName?.value?.trim();
      if (!name) return feedback("[data-add-feedback]", "Name is required.", "#e05050");

      const list = getRelations(actor);
      if (list.find(r => r.name.toLowerCase() === name.toLowerCase()))
        return feedback("[data-add-feedback]", `"${name}" already exists.`, "#e05050");

      const rel = {
        id:      uid("rel"),
        name,
        type:    f?.addType?.value   || "Faction",
        region:  f?.addRegion?.value || "",
        score:   Number(f?.addScore?.value)  || 0,
        status:  f?.addStatus?.value || "Neutral",
        notes:   f?.addNotes?.value  || "",
        created: nowIso()
      };
      list.push(rel);
      await setRelations(actor, list);
      await addHistory(actor, {
        type: "Faction Added", activity: rel.name,
        starsChange: 0, totalAfter: getStars(actor),
        outcome: `Score ${rel.score}`
      });

      // Clear form fields
      ["addName","addType","addRegion","addStatus","addNotes"].forEach(n => {
        if (f?.[n]) f[n].value = "";
      });
      if (f?.addScore) f.addScore.value = "0";

      refreshList();
      feedback("[data-add-feedback]", `✔ "${rel.name}" added.`, "#c9a66b");
    });

  }, 300);
}

async function openBoonAwarder(actor) {
  if (!actor) return ui.notifications.warn("Select a character first.");
  if (!game.user.isGM && !actor.isOwner) return ui.notifications.warn("You do not own this character.");

  const boons    = getBoons(actor);
  const catOpts  = ["All Activities",...BOON_CATEGORIES].map(c=>`<option>${safeText(c)}</option>`).join("");

  function buildBoonPresets(catFilter="All Activities") {
    const entries = catFilter==="All Activities"
      ? Object.entries(BOON_PRESETS)
      : [[catFilter, BOON_PRESETS[catFilter]||[]]];
    return entries.map(([cat,bs])=>`
      <div style="margin-bottom:14px;">
        <div style="font-size:13px;font-weight:bold;color:#8b0000;margin-bottom:6px;padding:4px 8px;background:rgba(139,0,0,0.1);border-radius:4px;">
          ✦ ${safeText(cat)} Boons
        </div>
        ${bs.map(b=>`
          <div style="border:1px solid #1a0000;border-radius:8px;padding:10px;margin-bottom:6px;background:rgba(0,0,0,0.4);">
            <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:6px;">
              <div>
                <div style="font-size:14px;font-weight:bold;color:#c9a66b;">${safeText(b.name)}</div>
                <div style="font-size:11px;color:#666;margin-top:1px;">${safeText(b.source)}</div>
              </div>
              <button type="button" data-grant-boon="${safeText(b.name)}" data-boon-cat="${safeText(cat)}"
                style="padding:3px 10px;border-radius:4px;border:1px solid #c9a66b;background:rgba(0,0,0,0.60);color:#c9a66b;cursor:pointer;font-size:11px;font-weight:bold;white-space:nowrap;">
                ✦ Grant
              </button>
            </div>
            <div style="font-size:12px;color:#cccccc;margin-top:5px;">${safeText(b.description)}</div>
          </div>`).join("")}
      </div>`).join("");
  }

  const boonListHtml = boons.length
    ? boons.map(b=>`
        <div style="border:1px solid #1a0000;border-radius:8px;padding:10px;margin-bottom:8px;background:rgba(0,0,0,0.4);">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <div>
              <div style="font-size:14px;font-weight:bold;color:#c9a66b;">${safeText(b.name)}</div>
              <div style="font-size:11px;color:#888;">${safeText(b.category||"General")} · ${safeText(b.created||"")}</div>
            </div>
            <div style="font-size:11px;color:#e05050;">${b.used?"✓ Used":b.expires?`Expires: ${safeText(b.expires)}`:"Active"}</div>
          </div>
          <div style="font-size:12px;color:#cccccc;margin-top:5px;">${safeText(b.description||"")}</div>
        </div>`).join("")
    : `<p style="color:#aaa;">No active boons.</p>`;

  const dialog = new Dialog({
    title: `✦ Boons & Blessings: ${actor.name}`,
    content: `<form>
      <div style="width:900px;max-width:96vw;background-image:url('https://i.imgur.com/WwkXkuk.png');background-size:cover;background-position:center;border:1px solid #8b0000;border-radius:10px;max-height:82vh;overflow-y:auto;">
        <div style="background:linear-gradient(135deg,#1a0000,#0d0d0d);border-bottom:2px solid #8b0000;padding:14px 20px;display:flex;align-items:center;gap:12px;">
          <span style="font-size:22px;">✦</span>
          <div><div style="font-size:18px;font-weight:bold;color:#c9a66b;">Boons & Blessings</div>
          <div style="font-size:12px;color:#888;">${safeText(actor.name)} · DMG + XGtE presets</div></div>
        </div>
        <div style="padding:0 16px;display:flex;gap:2px;border-bottom:1px solid #1a0000;padding-top:12px;background:rgba(0,0,0,0.72);">
          <button type="button" data-tab="active"  style="flex:1;padding:8px;border:none;border-bottom:3px solid #8b0000;background:rgba(139,0,0,0.15);color:#e05050;cursor:pointer;font-weight:bold;">📋 Active Boons</button>
          <button type="button" data-tab="presets" style="flex:1;padding:8px;border:none;border-bottom:3px solid transparent;background:transparent;color:#888;cursor:pointer;font-weight:bold;">📚 Grant Preset</button>
          <button type="button" data-tab="custom"  style="flex:1;padding:8px;border:none;border-bottom:3px solid transparent;background:transparent;color:#888;cursor:pointer;font-weight:bold;">✏️ Custom Boon</button>
        </div>
        <div style="padding:16px;background:rgba(0,0,0,0.65);">
          <div data-panel="active">${boonListHtml}</div>
          <div data-panel="presets" style="display:none;">
            <div style="display:flex;gap:8px;margin-bottom:12px;align-items:end;">
              <div style="flex:1;">
                <label style="font-size:11px;color:#888;display:block;margin-bottom:3px;">Downtime Activity</label>
                <select name="boonCatFilter" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;">${catOpts}</select>
              </div>
              <button type="button" data-filter-boons
                style="padding:7px 14px;border-radius:6px;border:1px solid #8b0000;background:rgba(139,0,0,0.2);color:#e05050;cursor:pointer;font-weight:bold;">🔍 Filter</button>
            </div>
            <div data-boon-preset-list>${buildBoonPresets()}</div>
          </div>
          <div data-panel="custom" style="display:none;">
            <h3 style="color:#c9a66b;margin-top:0;">✏️ Custom Boon</h3>
            <label style="color:#aaa;font-size:13px;">Name</label>
            <input name="boonName" type="text" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;" placeholder="e.g. Alchemical Mastery"><br>
            <label style="color:#aaa;font-size:13px;">Activity Category</label>
            <select name="boonCategory" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;">${catOpts}</select><br>
            <label style="color:#aaa;font-size:13px;">Description / Mechanical Effect</label>
            <textarea name="boonDescription" rows="4" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;margin-bottom:8px;"></textarea>
            <label style="color:#aaa;font-size:13px;">Expires (optional)</label>
            <input name="boonExpires" type="text" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;" placeholder="e.g. After 30 days, On next long rest…">
          </div>
        </div>
      </div>
    </form>`,
    buttons: {
      custom: { label: "✦ Grant Custom", callback: async (html) => {
        const f=html[0].querySelector("form").elements;
        if (!f.boonName?.value?.trim()) return ui.notifications.warn("Boon name required.");
        const list=getBoons(actor);
        const boon={id:uid("boon"),name:f.boonName.value.trim(),category:f.boonCategory?.value||"General",description:f.boonDescription?.value||"",expires:f.boonExpires?.value||"",created:nowIso(),used:false};
        list.push(boon); await setBoons(actor,list);
        await grantBoonToSheet(actor, boon);
        await addHistory(actor,{type:"Boon Granted",activity:boon.name,starsChange:0,totalAfter:getStars(actor),outcome:`Category: ${boon.category}`});
        await postChat(actor,simpleUpdateCard("✦ Boon Granted",safeText(actor.name),[{title:safeText(boon.name),content:`<strong>Category:</strong> ${safeText(boon.category)}<br><strong>Effect:</strong> ${safeText(boon.description)}`}]));
        ui.notifications.info(`Boon "${boon.name}" granted.`);
      } },
      close: { label: "Close", callback: () => {} }
    },
    default: "custom"
  }, { width: 900 });
  dialog.render(true);
  setTimeout(() => {
    const el=dialog.element[0];
    if (!el) return;
    const form=el.querySelector("form");
    el.querySelectorAll("[data-tab]").forEach(btn=>btn.addEventListener("click",()=>{
      const id=btn.dataset.tab;
      el.querySelectorAll("[data-tab]").forEach(b=>{const on=b.dataset.tab===id;b.style.cssText=`flex:1;padding:8px;border:none;cursor:pointer;font-weight:bold;${on?"border-bottom:3px solid #8b0000;background:rgba(139,0,0,0.15);color:#e05050;":"border-bottom:3px solid transparent;background:transparent;color:#888;"}`;});
      el.querySelectorAll("[data-panel]").forEach(p=>p.style.display=p.dataset.panel===id?"block":"none");
    }));
    const boonPresetList=el.querySelector("[data-boon-preset-list]");
    el.querySelector("[data-filter-boons]")?.addEventListener("click",()=>{
      if(boonPresetList) boonPresetList.innerHTML=buildBoonPresets(form?.elements?.boonCatFilter?.value||"All Activities");
      bindGrantBoon();
    });
    function bindGrantBoon(){
      el.querySelectorAll("[data-grant-boon]").forEach(btn=>btn.addEventListener("click",async()=>{
        const boonName=btn.dataset.grantBoon; const cat=btn.dataset.boonCat;
        const boonData=Object.values(BOON_PRESETS).flat().find(b=>b.name===boonName);
        if (!boonData) return;
        const list=getBoons(actor);
        const boon={id:uid("boon"),name:boonData.name,category:cat,description:boonData.description,source:boonData.source,created:nowIso(),used:false};
        list.push(boon); await setBoons(actor,list);
        await grantBoonToSheet(actor, boon);
        await addHistory(actor,{type:"Boon Granted (Preset)",activity:boon.name,starsChange:0,totalAfter:getStars(actor),outcome:safeText(cat),notes:boonData.description});
        await postChat(actor,simpleUpdateCard("✦ Boon Granted",safeText(actor.name),[{title:safeText(boon.name),content:`<strong>Category:</strong> ${safeText(cat)}<br><strong>Source:</strong> ${safeText(boonData.source)}<br><strong>Effect:</strong> ${safeText(boonData.description)}`}]));
        ui.notifications.info(`Boon "${boon.name}" granted.`);
      }));
    }
    bindGrantBoon();
  }, 300);
}

async function openHistoryViewer(actor) {
  if (!actor) return ui.notifications.warn("Select a character first.");
  if (!game.user.isGM && !actor.isOwner) return ui.notifications.warn("You do not own this character.");

  const dialog = new Dialog({
    title: `Downtime History: ${actor.name}`,
    content: `<div style="width:820px;max-width:96vw;max-height:82vh;overflow-y:auto;">${buildHistoryCard(actor)}</div>`,
    buttons: {
      send: { label: "Send History to Chat", callback: async (html) => {
          await postChat(actor, buildHistoryCard(actor));
          ui.notifications.info(`${actor.name}'s downtime history sent to chat.`);
        } },
      close: { label: "Close", callback: () => {} }
    },
    default: "send"
  }, { width: 820 });
  dialog.render(true);
}

