async function openStarTracker() {
  if (!game.user.isGM) return ui.notifications.warn("Only the GM can use the star tracker.");

  const actors     = characterActors();
  const actorOpts  = actors.map(a => `<option value="${a.id}">${safeText(a.name)} — ${getStars(a)} star(s)</option>`).join("");
  const actorList  = actors.map(a => `<li><strong>${safeText(a.name)}</strong>: ${getStars(a)} ${starIcons(getStars(a))}</li>`).join("");

  const dialog = new Dialog({
    title: "GM Downtime Star Tracker",
    content: `
      <form>
        <div style="width:560px;max-width:95vw;max-height:82vh;overflow-y:auto;">
          ${outerCard("⭐ GM Downtime Star Tracker", "Award or Remove Stars", `
            ${sectionBox("🌟 Current Star Totals", `<ul>${actorList || "<li>No character actors found.</li>"}</ul>`, "#8b0000", "rgba(0,0,0,0.42)", "#c9a66b")}
            <label>Character</label><select name="actorId" style="width:100%;">${actorOpts}</select><br><br>
            <label>Stars to Add / Remove</label><input name="amount" type="number" value="1" style="width:100%;"><br><br>
            <label>Reason</label><textarea name="reason" rows="3" style="width:100%;" placeholder="Example: Completed a 3-star quest"></textarea>
          `)}
        </div>
      </form>
    `,
    buttons: {
      apply: { label: "Apply Change", callback: async (html) => {
          const form        = html[0].querySelector("form");
          const targetActor = game.actors.get(form.elements.actorId.value);
          if (!targetActor) return ui.notifications.warn("Character not found.");
          const amount   = Number(form.elements.amount.value) || 0;
          const reason   = form.elements.reason.value;
          const oldTotal = getStars(targetActor);
          const newTotal = Math.max(0, oldTotal + amount);
          await setStars(targetActor, newTotal);
          await addHistory(targetActor, {
            type: "Downtime Stars Updated", activity: "Star Tracker",
            starsChange: amount, totalAfter: newTotal,
            outcome: `${oldTotal} → ${newTotal}`, notes: reason
          });
          await postChat(targetActor, simpleUpdateCard(
            amount >= 0 ? "⭐ Downtime Stars Awarded" : "⚠ Downtime Stars Removed",
            safeText(targetActor.name),
            [{ title: "🌟 Star Change",
               content: `<strong>Change:</strong> ${amount >= 0 ? "+" : ""}${amount}<br><strong>Old Total:</strong> ${oldTotal} ${starIcons(oldTotal)}<br><strong>New Total:</strong> ${newTotal} ${starIcons(newTotal)}<br><strong>Reason:</strong> ${safeText(reason || "None")}`,
               border: amount >= 0 ? "#8b0000" : "#9b4d4d",
               bg:     amount >= 0 ? "rgba(0,0,0,0.42)" : "rgba(180,70,70,0.08)",
               color:  amount >= 0 ? "#c9a66b" : "#ff9c9c"
            }]
          ));
          ui.notifications.info(`${targetActor.name} now has ${newTotal} downtime star(s).`);
        } },
      close: { label: "Close", callback: () => {} }
    },
    default: "apply"
  }, { width: 560 });
  dialog.render(true);
}

