// ── Grant boon as a visible item on the character sheet ──────────────────────
// Boons are saved as flags (tracked in the Boons dialog) AND created as
// consumable/loot items on the actor's sheet so they are visible during play.
async function grantBoonToSheet(actor, boon) {
  const expires = boon.expires ? `<p><strong>Expires:</strong> ${safeText(boon.expires)}</p>` : "";
  const source  = boon.source  ? `<p><strong>Source:</strong> ${safeText(boon.source)}</p>` : "";
  await actor.createEmbeddedDocuments("Item", [{
    name: `✦ Boon: ${boon.name}`,
    type: "feat",   // feat type renders cleanly on dnd5e sheet as a feature
    img:  "https://assets.forge-vtt.com/65e70ddcf8447871c18a2b4d/macros/ChatGPT%20Image%20May%206%2C%202026%2C%2001_30_05%20PM.png",
    system: {
      description: { value:
        `<p><strong style="color:#c9a66b;">✦ Downtime Boon — ${safeText(boon.category)}</strong></p>
         <p>${safeText(boon.description)}</p>
         ${source}${expires}
         <hr><p><em>Granted via Downtime Master. Mark as used when spent.</em></p>`
      }
    }
  }]);
}

// ── Complication Manager ──────────────────────────────────────────────────────
// GM tool — shows all complication tables, lets GM roll a specific one or
// view recent complications from the party's history.
async function openComplicationManager() {
  const COMP_TABLES = COMPLICATION_TABLES ?? {};
  const tableNames  = Object.keys(COMP_TABLES);

  function buildTableHtml(selected) {
    const rows = COMP_TABLES[selected];
    if (!rows?.length) return `<p style="color:#aaa;">No entries for ${safeText(selected)}.</p>`;
    return `<table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead><tr style="border-bottom:1px solid #3a0000;">
        <th style="text-align:left;padding:4px 6px;color:#c9a66b;width:40px;">d10</th>
        <th style="text-align:left;padding:4px 6px;color:#c9a66b;">Complication</th>
      </tr></thead>
      <tbody>${rows.map((r, i) =>
        `<tr style="border-bottom:1px solid #1a0000;background:${i%2===0?"rgba(0,0,0,0.3)":"rgba(0,0,0,0.1)"};">
          <td style="padding:4px 6px;color:#888;">${i+1}</td>
          <td style="padding:4px 6px;color:#f0f0f0;">${safeText(r)}</td>
        </tr>`).join("")}
      </tbody>
    </table>`;
  }

  const tableOptions = tableNames.map(n =>
    `<option value="${safeText(n)}">${safeText(n)}</option>`).join("");
  const firstTable   = tableNames[0] || "Custom";

  const dialog = new Dialog({
    title: "⚠ Complication Manager (GM)",
    content: `<form>
      <div style="width:680px;max-width:96vw;max-height:82vh;overflow-y:auto;background-image:url('https://i.imgur.com/WwkXkuk.png');background-size:cover;background-position:center;border:1px solid #8b0000;border-radius:10px;">
        <div style="background:linear-gradient(90deg,rgba(26,0,0,0.95),rgba(45,0,0,0.92));padding:14px 20px;border-bottom:2px solid #c9a66b;">
          <div style="font-size:18px;font-weight:bold;color:#c9a66b;">⚠ Complication Tables</div>
          <div style="font-size:12px;color:#888;">Roll a complication or view tables by activity</div>
        </div>
        <div style="background:rgba(0,0,0,0.72);padding:16px;">
          <div style="display:grid;grid-template-columns:1fr auto;gap:8px;align-items:end;margin-bottom:16px;">
            <div>
              <label style="font-size:12px;color:#aaa;display:block;margin-bottom:4px;">Activity / Table</label>
              <select name="compTable" style="width:100%;background:#111;border:1px solid #333;color:#f0f0f0;padding:6px;border-radius:4px;">
                ${tableOptions}
              </select>
            </div>
            <button type="button" data-roll-comp
              style="padding:8px 16px;border-radius:6px;border:1px solid #c9a66b;background:rgba(201,166,75,0.15);color:#c9a66b;cursor:pointer;font-weight:bold;white-space:nowrap;">
              🎲 Roll d10
            </button>
          </div>

          <div data-roll-result style="min-height:48px;padding:10px;border:1px solid #3a0000;border-radius:6px;background:rgba(139,0,0,0.15);margin-bottom:16px;display:none;">
            <div style="font-size:12px;color:#888;margin-bottom:4px;">Roll Result</div>
            <div data-roll-text style="font-size:15px;font-weight:bold;color:#f0f0f0;"></div>
          </div>

          <div data-table-display style="max-height:400px;overflow-y:auto;">
            ${buildTableHtml(firstTable)}
          </div>
        </div>
      </div>
    </form>`,
    buttons: {
      close: { label: "Close", callback: () => {} }
    },
    default: "close"
  }, { width: 680 });

  dialog.render(true);

  setTimeout(() => {
    const el   = dialog.element[0];
    if (!el) return;
    const form = el.querySelector("form");
    const tableDisplay  = el.querySelector("[data-table-display]");
    const rollResult    = el.querySelector("[data-roll-result]");
    const rollText      = el.querySelector("[data-roll-text]");
    const tableSel      = form?.elements?.compTable;

    tableSel?.addEventListener("change", () => {
      if (tableDisplay) tableDisplay.innerHTML = buildTableHtml(tableSel.value);
      if (rollResult)   rollResult.style.display = "none";
    });

    el.querySelector("[data-roll-comp]")?.addEventListener("click", () => {
      const table = COMP_TABLES[tableSel?.value];
      if (!table?.length) return;
      const roll   = Math.floor(Math.random() * 10);   // 0-9 → index
      const result = table[roll];
      if (rollResult) rollResult.style.display = "block";
      if (rollText)   rollText.innerHTML =
        `<span style="color:#c9a66b;">d10 = ${roll + 1}</span> — ${safeText(result)}`;
    });
  }, 200);
}

async function openWeeklySummary() {
  if (!game.user.isGM) return ui.notifications.warn("Only the GM can create a weekly summary.");

  const actors  = characterActors();
  const content = outerCard("📅 Weekly Downtime Summary", new Date().toLocaleDateString(),
    actors.map(actorSummaryHtml).join("") || "<p>No character actors found.</p>"
  );

  const dialog = new Dialog({
    title: "Weekly Downtime Summary",
    content: `<div style="width:840px;max-width:96vw;max-height:82vh;overflow-y:auto;">${content}</div>`,
    buttons: {
      send: { label: "Send Summary to Chat", callback: async (html) => {
          await ChatMessage.create({ content });
          ui.notifications.info("Weekly downtime summary sent to chat.");
        } },
      close: { label: "Close", callback: () => {} }
    },
    default: "send"
  }, { width: 840 });
  dialog.render(true);
}

// ══════════════════════════════════════════════════════
// DIALOG: GM SYNC (formerly standalone Macro 1)
// ══════════════════════════════════════════════════════

async function openGmSync() {
  if (!game.user.isGM) return ui.notifications.warn("Only the GM can run the sync.");

  ui.notifications.info("Syncing approved requests to projects / training tracks…");
  const results = await syncAll();

  const sectionHtml = results.length
    ? results.map(r => {
        const item = r.item;
        return sectionBox(
          `${r.type}: ${safeText(item.name)}`,
          `<strong>Character:</strong> ${safeText(r.actor.name)}<br>
           <strong>Activity:</strong> ${safeText(r.request.activity)}<br>
           ${progressBar(item.progress, item.target, item.complete ? "#c9a66b" : "#c9a66b")}
           <strong>Status:</strong> ${item.complete ? "Complete" : "In Progress"}<br>
           <strong>DC:</strong> ${Number(item.dc) || 10}<br>
           <strong>Rolls Required:</strong> ${Number(item.rollsRequired) || 1}<br>
           <strong>Progress on Success:</strong> ${Number(item.progressOnSuccess) || 25}<br>
           <strong>Progress on Failure:</strong> ${Number(item.progressOnFailure) || 5}<br>
           <strong>Star Cost:</strong> ${Number(item.starCost) || 0}`,
          item.complete ? "#8b0000" : "#8b0000",
          item.complete ? "rgba(0,0,0,0.42)" : "rgba(0,0,0,0.38)",
          item.complete ? "#c9a66b" : "#c9a66b"
        );
      }).join("")
    : `<p>No approved crafting, scribing, or training requests needed syncing.</p>`;

  await ChatMessage.create({
    content: outerCard("🧑‍⚖️ GM Downtime Sync Complete", "Requests → Projects / Training", sectionHtml)
  });
  ui.notifications.info(`Downtime sync complete. ${results.length} item(s) created or updated.`);
}

// ══════════════════════════════════════════════════════
// DIALOG: BLUEPRINT BROWSER (standalone, accessible from hub)
// ══════════════════════════════════════════════════════

async function openBlueprintBrowser(actor) {
  // actor is optional — if provided, "Start This Project" button pre-populates Crafting Tracker
  const bpCatOptions = ["All Affinities", ...BLUEPRINT_CATEGORIES]
    .map(c => `<option value="${safeText(c)}">${safeText(c)}</option>`).join("");

  const rarityOptions = ["All Rarities", "Common", "Uncommon", "Rare", "Very Rare"]
    .map(r => `<option value="${safeText(r)}">${safeText(r)}</option>`).join("");

  const bpOptions = BLUEPRINT_CATALOGUE
    .map(b => `<option value="${safeText(b.name)}"
        data-aff="${safeText(b.affinity)}"
        data-rarity="${safeText(b.rarity)}"
        data-skill="${b.skillLevel}"
        data-dc="${b.dc}"
        data-tool="${safeText(b.tool)}"
        data-target="${b.progressTarget}"
        data-time="${safeText(b.timeEstimate)}"
        data-stars="${b.starCost}"
        data-gold="${safeText(b.goldCost)}"
      >${safeText(b.name)} [${safeText(b.rarity)} — Skill ${b.skillLevel} — ${safeText(b.affinity)}]</option>`)
    .join("");

  // Build the full catalogue card list for scrollable browsing
  function buildBlueprintListHtml(filter = "All Affinities", rarityFilter = "All Rarities") {
    const filtered = BLUEPRINT_CATALOGUE.filter(b =>
      (filter === "All Affinities" || b.affinity === filter) &&
      (rarityFilter === "All Rarities" || b.rarity === rarityFilter)
    );
    if (!filtered.length) return `<p style="color:#aaa;">No blueprints match the selected filters.</p>`;

    return filtered.map(b => {
      const matLines = b.materials.map(m => `<li style="margin-left:16px;">${m.qty}× ${safeText(m.name)} (${safeText(m.unit)})</li>`).join("");
      const limitLines = b.limitations.map(l => `<li style="margin-left:16px;">${safeText(l)}</li>`).join("");
      const ritualLines = b.ritual.map((r, i) => `<li style="margin-left:16px;"><strong>${i + 1}.</strong> ${safeText(r)}</li>`).join("");

      const rarityColour = {
        "Common": "#c9a66b", "Uncommon": "#c9a66b",
        "Rare": "#c9a66b",   "Very Rare": "#ff9c9c", "Extremely Rare": "#d0a0ff"
      }[b.rarity] || "#cccccc";

      return `
        <div style="border:1px solid #555;border-radius:10px;padding:14px;margin-bottom:16px;background:rgba(255,255,255,0.03);">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap;">
            <div>
              <div style="font-size:18px;font-weight:bold;color:#c9a66b;">${safeText(b.name)}</div>
              <div style="font-size:13px;color:#aaa;margin-top:2px;">
                ${safeText(b.affinity)} &nbsp;|&nbsp;
                <span style="color:${rarityColour};">${safeText(b.rarity)}</span> &nbsp;|&nbsp;
                Skill Level ${b.skillLevel} &nbsp;|&nbsp;
                Tool: ${safeText(b.tool)}
              </div>
            </div>
            <div style="font-size:13px;text-align:right;color:#cccccc;white-space:nowrap;">
              DC ${b.dc} &nbsp;|&nbsp; ⭐ ${b.starCost}/session<br>
              Progress Target: ${b.progressTarget}<br>
              Time: ${safeText(b.timeEstimate)}
            </div>
          </div>

          <div style="margin-top:10px;font-size:14px;color:#cccccc;line-height:1.5;">${safeText(b.description)}</div>

          <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px;">
            <div>
              <div style="font-size:13px;font-weight:bold;color:#c9a66b;margin-bottom:4px;">📦 Required Materials</div>
              <ul style="font-size:13px;color:#cccccc;margin:0;padding:0;list-style:disc;">${matLines}</ul>
            </div>
            <div>
              <div style="font-size:13px;font-weight:bold;color:#c9a66b;margin-bottom:4px;">💰 Gold Cost</div>
              <div style="font-size:13px;color:#cccccc;">${safeText(b.goldCost)}</div>
              <div style="font-size:13px;font-weight:bold;color:#c9a66b;margin-top:8px;margin-bottom:4px;">📊 Progress</div>
              <div style="font-size:13px;color:#cccccc;">
                Success: +${b.progressPerSuccess} pts<br>
                Failure: +${b.progressPerFailure} pts<br>
                Target: ${b.progressTarget} pts
              </div>
            </div>
          </div>

          <details style="margin-top:10px;">
            <summary style="cursor:pointer;font-size:13px;font-weight:bold;color:#c9a66b;">📜 Ritual Steps (click to expand)</summary>
            <ul style="font-size:13px;color:#cccccc;margin:6px 0 0 0;padding:0;list-style:none;">${ritualLines}</ul>
          </details>

          <details style="margin-top:6px;">
            <summary style="cursor:pointer;font-size:13px;font-weight:bold;color:#ff9c9c;">⚠ Limitations (click to expand)</summary>
            <ul style="font-size:13px;color:#cccccc;margin:6px 0 0 0;padding:0;list-style:disc;">${limitLines}</ul>
          </details>

          <div style="margin-top:10px;padding:8px;background:rgba(0,0,0,0.38);border:1px solid #8b0000;border-radius:6px;font-size:13px;">
            <strong style="color:#c9a66b;">🏆 Reward on Completion:</strong><br>
            <span style="color:#cccccc;">${safeText(b.reward)}</span>
          </div>
        </div>
      `;
    }).join("");
  }

  const dialog = new Dialog({
    title: "📖 Downtime Master — Blueprint Catalogue",
    content: `
      <form>
        <div style="width:900px;max-width:96vw;max-height:82vh;overflow-y:auto;display:flex;flex-direction:column;">
          ${outerCard("📖 Blueprint Catalogue", `${BLUEPRINT_CATALOGUE.length} blueprints available`, `

            <div style="display:grid;grid-template-columns:1fr 1fr auto;gap:10px;align-items:end;margin-bottom:14px;">
              <div>
                <label style="font-size:13px;color:#aaa;display:block;margin-bottom:4px;">Filter by Affinity</label>
                <select name="bpCatFilter" style="width:100%;">${bpCatOptions}</select>
              </div>
              <div>
                <label style="font-size:13px;color:#aaa;display:block;margin-bottom:4px;">Filter by Rarity</label>
                <select name="bpRarityFilter" style="width:100%;">${rarityOptions}</select>
              </div>
              <div>
                <button type="button" data-dt-filter-blueprints
                  style="padding:8px 16px;border-radius:6px;border:1px solid #c9a66b;background:#1a0000;color:#c9a66b;cursor:pointer;font-weight:bold;white-space:nowrap;">
                  🔍 Apply Filter
                </button>
              </div>
            </div>

            ${actor ? `
              <div style="margin-bottom:14px;padding:10px;border:1px solid #8b0000;border-radius:8px;background:rgba(90,140,90,0.06);">
                <div style="font-size:13px;color:#aaa;margin-bottom:6px;">Quick-start a project for <strong style="color:#c9a66b;">${safeText(actor.name)}</strong>:</div>
                <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                  <select name="quickBpSelect" style="flex:1;min-width:240px;">${bpOptions}</select>
                  <button type="button" data-dt-quick-start
                    style="padding:8px 16px;border-radius:6px;border:1px solid #c9a66b;background:rgba(0,0,0,0.60);color:#c9a66b;cursor:pointer;font-weight:bold;white-space:nowrap;">
                    ➕ Start This Project
                  </button>
                </div>
                <div style="font-size:11px;color:#aaa;margin-top:4px;">This immediately creates the project in your Crafting Tracker with all blueprint values pre-filled.</div>
              </div>
            ` : `<div style="margin-bottom:10px;font-size:13px;color:#aaa;">Select a character from the hub first to enable quick-start project creation.</div>`}

            <div data-bp-list style="overflow-y:auto;max-height:580px;padding-right:6px;">
              ${buildBlueprintListHtml()}
            </div>
          `)}
        </div>
      </form>
    `,
    buttons: {
      close: { label: "Close", callback: () => {} }
    },
    default: "close"
  }, { width: 900 });

  dialog.render(true);

  setTimeout(() => {
    const el = dialog.element[0];
    if (!el) return;
    const form = el.querySelector("form");
    if (!form) return;

    const listEl   = el.querySelector("[data-bp-list]");
    const filterBtn = el.querySelector("[data-dt-filter-blueprints]");
    const quickBtn  = el.querySelector("[data-dt-quick-start]");

    // Apply filter and re-render the list
    function applyFilter() {
      const cat    = form.elements.bpCatFilter?.value    || "All Affinities";
      const rarity = form.elements.bpRarityFilter?.value || "All Rarities";
      if (listEl) listEl.innerHTML = buildBlueprintListHtml(cat, rarity);
    }

    if (filterBtn) filterBtn.addEventListener("click", applyFilter);

    // Quick-start: create a project directly from the dropdown
    if (quickBtn && actor) {
      quickBtn.addEventListener("click", async () => {
        const sel = form.elements.quickBpSelect;
        const bpName = sel?.value;
        if (!bpName) return ui.notifications.warn("Select a blueprint first.");
        const bp = BLUEPRINT_CATALOGUE.find(b => b.name === bpName);
        if (!bp) return;

        const list = getProjects(actor);
        // Avoid duplicate names
        if (list.some(p => p.name === bp.name && !p.complete)) {
          return ui.notifications.warn(`${bp.name} is already an active project for ${actor.name}.`);
        }

        const project = {
          id: uid("proj"),
          name: bp.name,
          progress: 0,
          target: bp.progressTarget,
          rarity: `${bp.rarity} (Skill ${bp.skillLevel})`,
          tool: bp.tool,
          materials: bp.materials.map(m => `${m.qty}× ${m.name} (${m.unit})`).join("\n"),
          reward: bp.reward,
          timeEstimate: bp.timeEstimate,
          goldCost: bp.goldCost,
          blueprintRef: bp.name,
          created: nowIso(),
          complete: false,
          // Workbench fields — these map to what applyWorkItemDefaults reads
          dc:               bp.dc,
          rollsRequired:    1,
          progressOnSuccess: bp.progressPerSuccess,  // workbench reads progressOnSuccess
          progressOnFailure: bp.progressPerFailure,  // workbench reads progressOnFailure
          checkKey:         bp.checkKey,
          ability:          bp.ability,
          starCost:         bp.starCost
        };

        list.push(project);
        await setProjects(actor, list);
        await addHistory(actor, {
          type: "Crafting Project Created (Blueprint)",
          activity: bp.name,
          starsChange: 0, totalAfter: getStars(actor),
          outcome: `Blueprint project started: 0/${bp.progressTarget}`,
          resources: project.materials,
          notes: `${bp.affinity} | ${bp.rarity} | Skill ${bp.skillLevel} | Est. ${bp.timeEstimate}`
        });

        await postChat(actor, outerCard("📖 Blueprint Project Started", safeText(actor.name), `
          ${sectionBox(`🛠 ${safeText(bp.name)}`,
            `<strong>Affinity:</strong> ${safeText(bp.affinity)}<br>
             <strong>Rarity:</strong> ${safeText(bp.rarity)}<br>
             <strong>Skill Level Required:</strong> ${bp.skillLevel}<br>
             <strong>Tool:</strong> ${safeText(bp.tool)}<br>
             <strong>DC:</strong> ${bp.dc}<br>
             ${progressBar(0, bp.progressTarget, "#c9a66b")}
             <strong>Time Estimate:</strong> ${safeText(bp.timeEstimate)}<br>
             <strong>Gold Cost:</strong> ${safeText(bp.goldCost)}`,
            "#8b0000", "rgba(0,0,0,0.38)", "#c9a66b"
          )}
          ${sectionBox("📦 Required Materials",
            `<ul style="margin:0;padding-left:18px;">${bp.materials.map(m => `<li>${m.qty}× ${safeText(m.name)} (${safeText(m.unit)})</li>`).join("")}</ul>`,
            "#8b0000", "rgba(0,0,0,0.42)", "#c9a66b"
          )}
          ${sectionBox("🏆 Reward on Completion", safeText(bp.reward), "#8b0000", "rgba(0,0,0,0.38)", "#c9a66b")}
        `));

        ui.notifications.info(`"${bp.name}" added to ${actor.name}'s Crafting Projects. Open the Workbench to begin work.`);
      });
    }
  }, 250);
}

