// ── Shared treasure rolling logic ───────────────────────

function treasureRollD100() {
  return Math.floor(Math.random() * 100) + 1;
}

function treasureChooseWeighted(weightedList) {
  const total = weightedList.reduce((s, e) => s + e[1], 0);
  let roll    = Math.random() * total;
  for (const [value, weight] of weightedList) {
    if (roll < weight) return value;
    roll -= weight;
  }
  return weightedList[0][0];
}

function treasureRollOnTable(tableKey) {
  const roll = treasureRollD100();
  const row  = TREASURE_TABLES[tableKey].find(([min, max]) => roll >= min && roll <= max);
  return { table: tableKey, d100: roll, baseName: row[2], name: row[2], category: row[3] };
}

function treasureRandomSpell(level) {
  const list = TREASURE_SPELLS[level];
  return list[Math.floor(Math.random() * list.length)];
}

function treasureScrollLevel(name) {
  if (name.includes("cantrip")) return "cantrip";
  if (name.includes("1st"))     return 1;
  if (name.includes("2nd"))     return 2;
  if (name.includes("3rd"))     return 3;
  if (name.includes("4th"))     return 4;
  if (name.includes("5th"))     return 5;
  if (name.includes("6th"))     return 6;
  if (name.includes("7th"))     return 7;
  if (name.includes("8th"))     return 8;
  if (name.includes("9th"))     return 9;
  return null;
}

function treasureResolveScroll(item) {
  if (!item.name.startsWith("Spell scroll")) return item;
  const level = treasureScrollLevel(item.name);
  const spell = treasureRandomSpell(level);
  return { ...item, spell, scrollLevel: level, name: `${item.name}: ${spell}` };
}

function treasureResolveSpecial(item) {
  // Figurine of wondrous power — pick a random variant
  if (item.baseName === "Figurine of wondrous power") {
    const variants = [
      "Figurine of wondrous power (bronze griffon)",
      "Figurine of wondrous power (ebony fly)",
      "Figurine of wondrous power (golden lions)",
      "Figurine of wondrous power (ivory goats)",
      "Figurine of wondrous power (marble elephant)",
      "Figurine of wondrous power (onyx dog)",
      "Figurine of wondrous power (onyx dog)",
      "Figurine of wondrous power (serpentine owl)"
    ];
    item.name = item.baseName = variants[Math.floor(Math.random() * variants.length)];
  }
  // Belt of frost or stone
  if (item.baseName === "Belt of frost or stone giant strength") {
    item.name = item.baseName = Math.random() < 0.5
      ? "Belt of frost giant strength"
      : "Belt of stone giant strength";
  }
  // Magic armor — random +2/+3 variant
  if (item.baseName === "Magic armor") {
    const variants = [
      "Armor, +2 half plate","Armor, +2 half plate",
      "Armor, +2 plate","Armor, +2 plate",
      "Armor, +3 studded leather","Armor, +3 studded leather",
      "Armor, +3 breastplate","Armor, +3 breastplate",
      "Armor, +3 splint","Armor, +3 splint",
      "Armor, +3 half plate","Armor, +3 plate"
    ];
    item.name = item.baseName = variants[Math.floor(Math.random() * variants.length)];
  }
  return item;
}

function treasureIsDuplicate(item, results) {
  if (!results.some(r => r.name === item.name)) return false;
  if (item.category === "consumable") return false;
  if (item.category === "scroll")     return false;
  return true;
}

function treasureGenerate(tierNum, sizeKey) {
  const cfg     = TREASURE_TIER_CONFIG[tierNum];
  const count   = cfg.sizes[sizeKey];
  const results = [];
  for (let i = 0; i < count; i++) {
    let attempts = 0, item;
    do {
      item = treasureRollOnTable(treasureChooseWeighted(cfg.weights));
      item = treasureResolveSpecial(item);
      item = treasureResolveScroll(item);
      attempts++;
    } while (treasureIsDuplicate(item, results) && attempts < cfg.maxAttempts);
    results.push(item);
  }
  return results;
}

