function treasureNormalize(name) {
  return String(name)
    .toLowerCase()
    .replace(/\+/g, " plus ")
    .replace(/['']/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function treasureCandidateNames(item) {
  if (item.category === "scroll") return ["Spell Scroll","Spell scroll","Scroll",item.baseName];
  const base  = item.baseName ?? item.name;
  const names = [base, item.name];
  if (TREASURE_ALIASES[base]) names.push(...TREASURE_ALIASES[base]);
  return [...new Set(names)];
}

// ── Spell Scroll Scribe lookup ────────────────────────
// When we need a spell scroll item, first check an actor called
// "Spell Scroll Scribe" for a pre-made scroll matching the spell.
// This ensures every scroll distributed (shop or treasure) is
// properly assigned to a specific spell from the existing inventory.
// Falls back to Item.createScrollFromSpell if available, then
// to a generic compendium "Spell Scroll" item.

const SCROLL_SCRIBE_ACTOR_NAME = "Spell Scroll Scribe";

async function findScrollFromScribe(spellName, scrollLevelLabel) {
  const scribe = game.actors.getName(SCROLL_SCRIBE_ACTOR_NAME);
  if (!scribe) return null;

  // Try exact spell name match first
  if (spellName) {
    const exact = scribe.items.find(i =>
      i.type === "consumable" &&
      i.name.toLowerCase().includes(spellName.toLowerCase())
    );
    if (exact) return exact.toObject();
  }

  // Match by level — collect ALL scrolls at that level, then pick randomly.
  // This ensures the shop shows a variety of spells rather than always the same one.
  if (scrollLevelLabel) {
    // Normalise the level label to something matchable:
    // "Spell Scroll (1st Level)" → "(1st level)"  |  "cantrip" → "cantrip"
    const lbl       = scrollLevelLabel.toLowerCase();
    const levelFrag = lbl.replace(/spell\s*scroll\s*/i, "").trim();  // "(1st level)" or "cantrip" etc.

    const matches = scribe.items.filter(i =>
      i.type === "consumable" &&
      i.name.toLowerCase().includes("spell scroll") &&
      i.name.toLowerCase().includes(levelFrag.replace(/[()]/g, "").trim())
    );
    if (matches.length) {
      const picked = matches[Math.floor(Math.random() * matches.length)];
      return picked.toObject();
    }
  }

  // Last resort: any spell scroll on the scribe
  const all = scribe.items.filter(i =>
    i.type === "consumable" &&
    i.name.toLowerCase().includes("spell scroll")
  );
  if (all.length) return all[Math.floor(Math.random() * all.length)].toObject();
  return null;
}

async function treasureFindCompendiumItem(item) {
  const candidates   = treasureCandidateNames(item).map(treasureNormalize);
  const packs        = game.packs.filter(p => p.documentName === "Item");
  let   looseMatch   = null;

  for (const pack of packs) {
    let index;
    try { index = await pack.getIndex({ fields: ["name","type","img"] }); }
    catch { continue; }

    let entry = index.find(i => candidates.includes(treasureNormalize(i.name)));
    if (entry) return await pack.getDocument(entry._id);

    entry = index.find(i => {
      const n = treasureNormalize(i.name);
      return candidates.some(c => n.includes(c) || c.includes(n));
    });
    if (entry && !looseMatch) looseMatch = { pack, entry };
  }

  return looseMatch ? await looseMatch.pack.getDocument(looseMatch.entry._id) : null;
}

function treasurePlaceholderItem(item, tierNum) {
  const isScroll = item.category === "scroll";
  return {
    name: item.name,
    type: "loot",
    img: isScroll
      ? "https://assets.forge-vtt.com/65e70ddcf8447871c18a2b4d/macros/ChatGPT%20Image%20May%206%2C%202026%2C%2001_30_05%20PM.png"
      : "https://assets.forge-vtt.com/65e70ddcf8447871c18a2b4d/macros/ChatGPT%20Image%20May%206%2C%202026%2C%2001_30_05%20PM.png",
    system: {
      quantity: 1, weight: 0,
      description: {
        value: `<p><strong>Generated Tier ${tierNum} Treasure.</strong></p>
                <p><strong>Source:</strong> Magic Item Table ${item.table}, d100 ${item.d100}.</p>
                ${isScroll ? `<p><strong>Assigned Spell:</strong> ${item.spell}</p>` : ""}
                <p><em>Placeholder: matching compendium item was not found.</em></p>`
      }
    }
  };
}

async function treasureMakeActorItem(item, tierNum) {
  let data;

  if (item.category === "scroll") {
    // For scrolls: try to get a pre-assigned scroll from the Spell Scroll Scribe actor.
    // This ensures the scroll has an actual spell assigned rather than being generic.
    const scribeData = await findScrollFromScribe(item.spell, item.baseName);
    if (scribeData) {
      data = scribeData;
      delete data._id;
      // Override name to include the specific spell if we have one
      if (item.spell && !data.name.toLowerCase().includes(item.spell.toLowerCase())) {
        data.name = `${item.baseName}: ${item.spell}`;
      }
    } else {
      // Try createScrollFromSpell if the spell name is known
      const Item5e = CONFIG?.Item?.documentClass;
      if (item.spell && typeof Item5e?.createScrollFromSpell === "function") {
        try {
          // Find the spell in compendiums
          const spellPacks = game.packs.filter(p => p.documentName === "Item");
          let spellDoc = null;
          for (const pack of spellPacks) {
            const idx = await pack.getIndex({ fields: ["name","type"] });
            const entry = idx.find(i => i.type === "spell" &&
              i.name.toLowerCase() === item.spell.toLowerCase());
            if (entry) { spellDoc = await pack.getDocument(entry._id); break; }
          }
          if (spellDoc) {
            const scroll = await Item5e.createScrollFromSpell(spellDoc, {}, { dialog: false });
            if (scroll) {
              data = scroll.toObject();
              delete data._id;
              data.name = `${item.baseName}: ${item.spell}`;
            }
          }
        } catch { /* fall through to compendium lookup */ }
      }
      if (!data) {
        const found = await treasureFindCompendiumItem(item);
        data = found ? found.toObject() : treasurePlaceholderItem(item, tierNum);
        delete data._id;
      }
    }
  } else {
    const found = await treasureFindCompendiumItem(item);
    data = found ? found.toObject() : treasurePlaceholderItem(item, tierNum);
    delete data._id;
  }

  data.name           = item.name;
  data.system         = data.system ?? {};
  data.system.quantity = 1;
  data.system.description = data.system.description ?? {};
  data.system.description.value = `
    ${data.system.description.value ?? ""}
    <hr>
    <p><strong>Generated Treasure:</strong> Tier ${tierNum} Magic Treasure</p>
    <p><strong>Rolled:</strong> Table ${item.table}, d100 ${item.d100}</p>
    ${item.spell ? `<p><strong>Spell Scroll Spell:</strong> ${item.spell}</p>` : ""}
  `;
  return data;
}

async function treasureAddToActor(actor, results, tierNum) {
  const itemData = [];
  for (const r of results) itemData.push(await treasureMakeActorItem(r, tierNum));
  await actor.createEmbeddedDocuments("Item", itemData);
}

// ── Chat result card using downtime styling ──────────────

function treasureResultCard(results, tierNum, sizeKey, destinationActor) {
  const cfg        = TREASURE_TIER_CONFIG[tierNum];
  const tierColour = cfg.colour;

  const catColour = {
    consumable:    "#c9a66b",
    scroll:        "#c9a66b",
    minorPermanent:"#b8860b",
    majorPermanent:"#ff9c9c",
    legendary:     "#d0a0ff"
  };
  const catLabel = {
    consumable:    "Consumable",
    scroll:        "Scroll",
    minorPermanent:"Minor Permanent",
    majorPermanent:"Major Permanent",
    legendary:     "Legendary"
  };

  // Use an HTML <table> — renders predictably in Foundry's narrow chat pane
  // regardless of flex/grid support in the embedded browser.
  const tableRows = results.map((item, i) => {
    const col  = catColour[item.category] || "#cccccc";
    const lbl  = catLabel[item.category]  || item.category;
    return `
      <tr style="border-bottom:1px solid rgba(255,255,255,0.06);">
        <td style="padding:5px 6px;color:#aaa;font-size:12px;text-align:right;white-space:nowrap;vertical-align:top;">${i + 1}.</td>
        <td style="padding:5px 4px;color:#aaa;font-size:12px;white-space:nowrap;vertical-align:top;">T${item.table}</td>
        <td style="padding:5px 4px;color:#888;font-size:11px;white-space:nowrap;vertical-align:top;">d${item.d100}</td>
        <td style="padding:5px 6px;font-weight:bold;color:#c0392b;vertical-align:top;word-break:break-word;">${safeText(item.name)}</td>
        <td style="padding:5px 4px;vertical-align:top;white-space:nowrap;text-align:right;">
          <span style="font-size:10px;padding:2px 6px;border-radius:10px;
                       color:${col};background:rgba(255,255,255,0.05);border:1px solid ${col};">
            ${lbl}
          </span>
        </td>
      </tr>
    `;
  }).join("");

  const tableHtml = `
    <table style="width:100%;border-collapse:collapse;font-family:'Signika',sans-serif;">
      <thead>
        <tr style="border-bottom:1px solid rgba(255,255,255,0.15);">
          <th style="padding:4px 6px;color:#888;font-size:11px;font-weight:normal;text-align:right;width:24px;">#</th>
          <th style="padding:4px 4px;color:#888;font-size:11px;font-weight:normal;text-align:left;width:28px;">Tbl</th>
          <th style="padding:4px 4px;color:#888;font-size:11px;font-weight:normal;text-align:left;width:30px;">Roll</th>
          <th style="padding:4px 6px;color:#888;font-size:11px;font-weight:normal;text-align:left;">Item</th>
          <th style="padding:4px 4px;color:#888;font-size:11px;font-weight:normal;text-align:right;">Type</th>
        </tr>
      </thead>
      <tbody>${tableRows}</tbody>
    </table>
  `;

  // Compact summary line
  const countsByType = results.reduce((acc, r) => {
    const lbl = catLabel[r.category] || r.category;
    acc[lbl] = (acc[lbl] || 0) + 1;
    return acc;
  }, {});
  const summaryLine = Object.entries(countsByType)
    .map(([lbl, n]) => `${n}× ${lbl}`)
    .join(" &nbsp;|&nbsp; ");

  return outerCard(
    `💰 Tier ${tierNum} Magic Treasure`,
    safeText(cfg.label),
    `
      <table style="width:100%;border-collapse:collapse;margin-bottom:12px;font-size:13px;color:#cccccc;">
        <tr>
          <td style="padding:3px 0;"><strong style="color:#aaa;">Destination:</strong></td>
          <td style="padding:3px 6px;font-weight:bold;color:#c0392b;">${safeText(destinationActor.name)}</td>
          <td style="padding:3px 0;text-align:right;"><strong style="color:#aaa;">Size:</strong></td>
          <td style="padding:3px 6px;color:#cccccc;">${safeText(cfg.sizeLabels[sizeKey]?.split("(")[0].trim() || sizeKey)}</td>
        </tr>
        <tr>
          <td style="padding:3px 0;"><strong style="color:#aaa;">Weighting:</strong></td>
          <td colspan="3" style="padding:3px 6px;color:#aaa;font-size:12px;">${safeText(cfg.weightLabel)}</td>
        </tr>
        <tr>
          <td style="padding:3px 0;"><strong style="color:#aaa;">Summary:</strong></td>
          <td colspan="3" style="padding:3px 6px;font-size:12px;color:#aaa;">${summaryLine}</td>
        </tr>
      </table>

      <div style="border:1px solid #1a0000;border-radius:8px;overflow:hidden;background:rgba(0,0,0,0.2);">
        ${tableHtml}
      </div>

      <p style="margin-top:10px;font-size:12px;color:#666;font-style:italic;">
        ✔ Items added to inventory. Consumables &amp; scrolls may repeat. Permanent items avoid duplicates.
      </p>
    `
  );
}

// ── Main dialog ──────────────────────────────────────────

async function openTreasureGenerator() {
  const allActors    = game.actors
    .filter(a => ["character","npc"].includes(a.type))
    .sort((a, b) => a.name.localeCompare(b.name));

  const actorOptions = allActors
    .map(a => `<option value="${a.id}">${safeText(a.name)}</option>`)
    .join("");

  const lootChestOption = game.actors.getName(LOOT_ACTOR_NAME)
    ? `<option value="partyLoot" selected>🏴‍☠️ ${safeText(LOOT_ACTOR_NAME)} (shared loot)</option>`
    : `<option value="partyLoot" disabled>🏴‍☠️ "${safeText(LOOT_ACTOR_NAME)}" (not found — create this actor first)</option>`;

  // Build the tier selection cards as clickable visual tiles
  const tierTiles = [1, 2, 3, 4].map(t => {
    const cfg = TREASURE_TIER_CONFIG[t];
    return `
      <label style="display:block;cursor:pointer;margin-bottom:8px;">
        <input type="radio" name="treasureTier" value="${t}" ${t === 1 ? "checked" : ""}
               style="display:none;" data-tier="${t}">
        <div data-tier-tile="${t}" style="
          padding:12px 14px;border-radius:8px;
          border:2px solid ${t === 1 ? cfg.colour : "#444"};
          background:${t === 1 ? `rgba(143,227,136,0.07)` : "rgba(255,255,255,0.02)"};
          transition:border-color 0.15s,background 0.15s;cursor:pointer;">
          <div style="display:flex;align-items:center;justify-content:space-between;">
            <div>
              <strong style="color:${cfg.colour};">Tier ${t}</strong>
              <span style="color:#cccccc;font-size:14px;margin-left:8px;">${safeText(cfg.label.split("—")[1]?.trim() || "")}</span>
            </div>
            <span style="font-size:11px;color:#aaa;">${safeText(cfg.weightLabel)}</span>
          </div>
          <div style="margin-top:6px;font-size:12px;color:#aaa;">
            Tables: ${cfg.weights.map(w => w[0]).join(", ")} &nbsp;|&nbsp;
            Sizes: ${Object.values(cfg.sizeLabels).join(" / ")}
          </div>
        </div>
      </label>
    `;
  }).join("");

  // Dynamic size options that update when tier changes
  function sizeOptionsHtml(tierNum) {
    const cfg = TREASURE_TIER_CONFIG[tierNum];
    return Object.entries(cfg.sizeLabels).map(([key, label]) =>
      `<option value="${key}" ${key === "standard" ? "selected" : ""}>${safeText(label)}</option>`
    ).join("");
  }

  const dialog = new Dialog({
    title: "💰 Magic Treasure Generator",
    content: `
      <form>
        <div style="width:740px;max-width:96vw;max-height:82vh;overflow-y:auto;">
          ${outerCard("💰 Magic Treasure Generator", "DMG Tables A–I • All Tiers", `

            ${sectionBox("🎯 Select Tier", tierTiles, "#8b0000", "rgba(255,210,120,0.03)", "#c9a66b")}

            ${sectionBox("⚖️ Hoard Size", `
              <select name="treasureSize" style="width:100%;font-size:14px;" id="dt-treasure-size">
                ${sizeOptionsHtml(1)}
              </select>
            `, "#8b0000", "rgba(0,0,0,0.5)", "#c9a66b")}

            ${sectionBox("📦 Send Loot To", `
              <select name="destination" style="width:100%;font-size:14px;">
                ${lootChestOption}
                <option value="selected">🎯 Currently Selected Token</option>
                ${actorOptions}
              </select>
              <div style="margin-top:6px;font-size:12px;color:#aaa;">
                Create an actor named "<strong>${safeText(LOOT_ACTOR_NAME)}</strong>" for shared party loot.
              </div>
            `, "#8b0000", "rgba(90,140,90,0.06)", "#c9a66b")}

            ${sectionBox("💬 Chat Display", `
              <select name="outputMode" style="width:100%;font-size:14px;">
                <option value="public" selected>👁 Show to Everyone</option>
                <option value="gm">🔒 Whisper to GM Only</option>
              </select>
            `, "#666", "rgba(255,255,255,0.02)", "#cccccc")}
          `)}
        </div>
      </form>
    `,
    buttons: {
      roll: { label: "🎲 Generate Loot & Add to Inventory", callback: async (html) => {
          const form      = html[0].querySelector("form");
          const tierNum   = Number(form.elements.treasureTier?.value  ?? form.querySelector("[name='treasureTier']:checked")?.value ?? 1);
          const sizeKey   = form.elements.treasureSize.value;
          const destVal   = form.elements.destination.value;
          const outputMode = form.elements.outputMode.value;

          // Resolve destination actor
          let destinationActor = null;
          if (destVal === "selected") {
            destinationActor = canvas.tokens.controlled[0]?.actor ?? null;
          } else if (destVal === "partyLoot") {
            destinationActor = game.actors.getName(LOOT_ACTOR_NAME) ?? null;
          } else {
            destinationActor = game.actors.get(destVal) ?? null;
          }

          if (!destinationActor) {
            return ui.notifications.error(
              `No valid destination actor found. Create an actor named "${LOOT_ACTOR_NAME}" or select a token.`
            );
          }

          ui.notifications.info("Generating treasure — searching compendiums…");

          const results = treasureGenerate(tierNum, sizeKey);
          await treasureAddToActor(destinationActor, results, tierNum);

          const chatContent = treasureResultCard(results, tierNum, sizeKey, destinationActor);
          const chatData = {
            user:    game.user.id,
            speaker: ChatMessage.getSpeaker({ actor: destinationActor }),
            content: chatContent
          };
          if (outputMode === "gm") {
            chatData.whisper = ChatMessage.getWhisperRecipients("GM").map(u => u.id);
          }
          await ChatMessage.create(chatData);

          ui.notifications.info(
            `Tier ${tierNum} treasure (${results.length} items) added to ${destinationActor.name}.`
          );
        } },
      close: { label: "Close", callback: () => {} }
    },
    default: "roll"
  }, { width: 740 });

  dialog.render(true);

  // Wire up tier tile selection and size dropdown update
  setTimeout(() => {
    const el = dialog.element[0];
    if (!el) return;
    const form     = el.querySelector("form");
    if (!form) return;
    const sizeSel  = form.elements.treasureSize;
    const tiles    = el.querySelectorAll("[data-tier-tile]");
    const radios   = form.querySelectorAll("[name='treasureTier']");

    function selectTier(tierNum) {
      // Update tile borders
      tiles.forEach(tile => {
        const t   = Number(tile.dataset.tierTile);
        const cfg = TREASURE_TIER_CONFIG[t];
        tile.style.borderColor  = t === tierNum ? cfg.colour : "#444";
        tile.style.background   = t === tierNum ? `rgba(${tierNum===1?"143,227,136":tierNum===2?"158,208,255":tierNum===3?"255,210,122":"255,156,156"},0.07)` : "rgba(255,255,255,0.02)";
      });
      // Update radio
      radios.forEach(r => { r.checked = Number(r.value) === tierNum; });
      // Update size dropdown
      sizeSel.innerHTML = sizeOptionsHtml(tierNum);
    }

    tiles.forEach(tile => {
      tile.addEventListener("click", () => selectTier(Number(tile.dataset.tierTile)));
    });

    // Also handle radio clicks directly
    radios.forEach(r => {
      r.addEventListener("change", () => selectTier(Number(r.value)));
    });
  }, 250);
}

